descriptor.templateCss:
.pj{
  --verde:#33513A; --verde-suave:#E4EBE6; --tinta:#3F3530; --gris:#786F68; --linea:#EEEAE6;
  --fondo:#FFFFFF; --crema:#F6F4F2; --ambar:#9A5B00; --ambar-suave:#FFF4E0;
  --rojo:#B3261E; --rojo-suave:#FBE9E7; --azul:#1F5C8A; --azul-suave:#E6EFF6;
  font-family:'Mulish',sans-serif; color:var(--tinta); background:var(--fondo);
  height:100%; display:flex; flex-direction:column; box-sizing:border-box; overflow:hidden; position:relative;
}
.pj *{box-sizing:border-box;}

/* Cabecera */
.pj-cabecera{display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap;padding:16px 20px 12px;border-bottom:1px solid var(--linea);flex-shrink:0;}
.pj-titulo-bloque{display:flex;align-items:center;gap:12px;}
.pj-icono{width:46px;height:46px;border-radius:50%;background:var(--verde-suave);color:var(--verde);display:flex;align-items:center;justify-content:center;flex-shrink:0;}
.pj-icono svg{width:26px;height:26px;}
.pj-titulo{font-family:'Playfair Display',serif;font-weight:800;font-size:26px;line-height:1.1;margin:0;}
.pj-semana{margin:3px 0 0;font-size:13px;color:var(--gris);font-weight:600;}
.pj-acciones{display:flex;align-items:center;gap:8px;flex-wrap:wrap;}
.pj-nav{display:flex;align-items:center;background:var(--crema);border-radius:999px;padding:2px;}
.pj button{font-family:inherit;cursor:pointer;border:none;transition:background .15s,color .15s,opacity .15s;}
.pj button:disabled{opacity:.45;cursor:default;}
.pj-btn-icono{width:30px;height:30px;border-radius:50%;background:transparent;color:var(--tinta);font-size:20px;line-height:1;}
.pj-btn-icono:hover{background:var(--verde-suave);}
.pj-btn-texto{background:transparent;color:var(--tinta);font-size:12px;font-weight:700;padding:6px 10px;border-radius:999px;}
.pj-btn-texto:hover:not(:disabled){background:var(--verde-suave);}
.pj-btn-sec{background:var(--verde-suave);color:var(--verde);font-size:12px;font-weight:700;padding:8px 12px;border-radius:999px;}
.pj-btn-sec:hover{background:#d3dfd6;}
.pj-btn-pri{background:var(--verde);color:#fff;font-size:12px;font-weight:700;padding:8px 14px;border-radius:999px;}
.pj-btn-pri:hover{background:#26402c;}

/* Progreso y avisos */
.pj-progreso{padding:10px 20px;font-size:12px;color:var(--gris);flex-shrink:0;}
.pj-progreso-barra{height:4px;background:var(--crema);border-radius:4px;margin-top:6px;overflow:hidden;}
.pj-progreso-barra i{display:block;height:100%;background:var(--verde);border-radius:4px;transition:width .3s;}
.pj-aviso{position:absolute;right:20px;top:74px;z-index:20;padding:8px 14px;border-radius:8px;font-size:12px;font-weight:700;box-shadow:0 4px 14px rgba(0,0,0,.12);}
.pj-aviso-ok{background:var(--verde);color:#fff;}
.pj-aviso-error{background:var(--rojo);color:#fff;}

/* Cuerpo */
.pj-cuerpo{flex:1;overflow:auto;padding:14px 20px 24px;}
.pj-vacio{text-align:center;padding:60px 12px;color:var(--gris);}
.pj-vacio strong{display:block;font-family:'Playfair Display',serif;font-size:20px;color:var(--tinta);margin-bottom:6px;}

/* KPIs */
.pj-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-bottom:10px;}
.pj-kpi{background:var(--crema);border-radius:10px;padding:10px 12px;}
.pj-kpi-t{font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--gris);}
.pj-kpi-v{font-size:24px;font-weight:800;color:var(--verde);margin-top:2px;font-variant-numeric:tabular-nums;}
.pj-kpi-v small{font-size:12px;font-weight:700;color:var(--gris);margin-left:4px;}
.pj-kpi-n{font-size:11px;color:var(--gris);margin-top:1px;}
.pj-kpi-alerta{background:var(--rojo-suave);}
.pj-kpi-alerta .pj-kpi-v{color:var(--rojo);}

/* Estado fijada / aprobada */
.pj-estado-fijada{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px;}
.pj-chip{font-size:12px;font-weight:700;padding:5px 10px;border-radius:999px;background:var(--verde-suave);color:var(--verde);}
.pj-chip-gris{background:var(--crema);color:var(--gris);}
.pj-chip-ok{background:var(--verde);color:#fff;}
.pj-chip-error{background:var(--rojo-suave);color:var(--rojo);}

/* Paneles */
.pj-panel{border:1px solid var(--linea);border-radius:10px;margin-bottom:14px;overflow:hidden;}
.pj-panel-titulo{font-family:'Playfair Display',serif;font-weight:700;font-size:17px;padding:10px 14px;border-bottom:1px solid var(--linea);display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;}
.pj-panel-titulo span{font-family:'Mulish',sans-serif;font-size:12px;font-weight:600;color:var(--gris);}

/* Tabla de días */
.pj-dias-wrap{overflow-x:auto;}
.pj-dias{width:100%;border-collapse:collapse;font-size:13px;min-width:720px;}
.pj-dias th{font-size:12px;font-weight:800;color:var(--gris);text-transform:uppercase;letter-spacing:.05em;padding:8px 6px;text-align:center;border-bottom:1px solid var(--linea);}
.pj-dias th small{display:block;font-size:15px;color:var(--tinta);letter-spacing:0;}
.pj-dias td{padding:7px 6px;text-align:center;border-bottom:1px solid var(--linea);font-variant-numeric:tabular-nums;}
.pj-dias td:first-child{text-align:left;font-weight:700;white-space:nowrap;padding-left:14px;}
.pj-dias td:first-child small{display:block;font-weight:500;color:var(--gris);font-size:11px;}
.pj-dias td:last-child{font-weight:700;color:var(--gris);white-space:nowrap;}
.pj-fila-meteo td{font-size:16px;line-height:1.15;}
.pj-fila-meteo td div{font-size:13px;font-weight:700;}
.pj-fila-meteo td small{font-size:11px;color:var(--azul);font-weight:700;}
.pj-fila-fuerte td{font-weight:800;font-size:15px;color:var(--verde);}
.pj-fila-disp td{background:#FBFAF8;}
.pj-input-disp{width:84px;max-width:100%;padding:5px 6px;border:1px solid #d9d3cd;border-radius:6px;font:inherit;font-weight:700;text-align:center;background:#fff;color:var(--tinta);}
.pj-input-disp:focus{outline:none;border-color:var(--verde);box-shadow:0 0 0 2px rgba(51,81,58,.15);}
.pj-fila-real td{color:var(--gris);font-size:12px;}
.pj-hoy{background:#F3F7F4 !important;}
th.pj-hoy{color:var(--verde) !important;}
.pj-sube{color:var(--ambar);font-weight:800;}
.pj-baja{color:var(--azul);font-weight:800;}
.pj-deficit{color:var(--rojo);font-weight:800;background:var(--rojo-suave);}
.pj-excedente{color:var(--verde);font-weight:800;}
.pj-gris{color:#b3aaa3;}

/* Propuestas */
.pj-propuestas{padding:6px 14px 10px;}
.pj-prop{display:flex;gap:12px;padding:9px 0;border-bottom:1px dashed var(--linea);font-size:13px;line-height:1.55;}
.pj-prop:last-child{border-bottom:none;}
.pj-prop-dia{flex:0 0 86px;font-weight:800;}
.pj-prop-deficit .pj-prop-dia{color:var(--rojo);}
.pj-prop-excedente .pj-prop-dia{color:var(--verde);}
.pj-prop-nota{color:var(--gris);font-size:12px;}
.pj-prop-vacio{color:var(--gris);font-size:13px;padding:8px 0;}
.pj-tag{display:inline-block;font-size:12px;font-weight:700;padding:1px 8px;border-radius:999px;margin:2px 2px 0 0;}
.pj-tag-parcial{background:var(--ambar-suave);color:var(--ambar);}
.pj-tag-aplazado{background:var(--rojo-suave);color:var(--rojo);}
.pj-tag-adelanto{background:var(--verde-suave);color:var(--verde);}
.pj-tag-balsa{background:var(--azul-suave);color:var(--azul);}

/* Tabla por grupo */
.pj-filtros{display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:10px 14px;border-bottom:1px solid var(--linea);}
.pj-sel-sector,.pj-buscar{font:inherit;font-size:13px;padding:6px 10px;border:1px solid #d9d3cd;border-radius:999px;background:#fff;color:var(--tinta);}
.pj-buscar{min-width:200px;}
.pj-check{font-size:12px;font-weight:600;color:var(--gris);display:flex;align-items:center;gap:6px;cursor:pointer;}
.pj-leyenda-grupos{display:flex;align-items:center;gap:4px;flex-wrap:wrap;}
.pj-ley{display:inline-block;width:10px;height:10px;border-radius:3px;margin-left:6px;vertical-align:-1px;}
.pj-grupos-wrap{overflow:auto;max-height:560px;}
.pj-grupos{width:100%;border-collapse:separate;border-spacing:0;font-size:13px;min-width:860px;}
.pj-grupos th{position:sticky;top:0;z-index:2;background:#fff;font-size:11px;font-weight:800;color:var(--gris);text-transform:uppercase;letter-spacing:.05em;padding:8px 5px;border-bottom:1px solid var(--linea);text-align:center;}
.pj-grupos th small{display:block;font-size:13px;color:var(--tinta);letter-spacing:0;text-transform:none;}
.pj-grupos td{padding:6px 5px;border-bottom:1px solid var(--linea);text-align:center;font-variant-numeric:tabular-nums;white-space:nowrap;}
.pj-grupos tbody tr:hover td{background:#F7F9F7;}
.pj-col-sector{width:52px;color:var(--gris);font-weight:700;}
.pj-col-grupo{text-align:left !important;font-weight:700;white-space:normal !important;min-width:170px;}
.pj-activo{color:var(--verde);font-size:10px;}
.pj-base{color:var(--gris);font-weight:700;}
.pj-sem{font-weight:800;color:var(--verde);}
.pj-c{min-width:58px;font-weight:700;position:relative;}
.pj-c-prev{color:var(--tinta);}
.pj-c-completo{background:#EAF2EC;color:var(--verde);}
.pj-c-parcial{background:var(--ambar-suave);color:var(--ambar);}
.pj-c-aplazado{background:var(--rojo-suave);color:var(--rojo);}
.pj-ley.pj-c-completo{background:#cfe2d4;}
.pj-ley.pj-c-parcial{background:#f5d9a8;}
.pj-ley.pj-c-aplazado{background:#f2c3bd;}
.pj-m{display:inline-block;font-size:10px;font-weight:800;width:15px;height:15px;line-height:15px;border-radius:4px;margin-right:4px;vertical-align:1px;}
.pj-m-r{background:#ffd600;color:#000;}
.pj-m-p{background:#455a64;color:#fff;}

@media (max-width:760px){
  .pj-titulo{font-size:21px;}
  .pj-cabecera,.pj-cuerpo{padding-left:12px;padding-right:12px;}
}

/* ============================== GEMELO DIGITAL ============================== */
.pj-pestanas{display:flex;gap:4px;background:var(--crema);border-radius:999px;padding:3px;}
.pj-pestana{background:transparent;color:var(--gris);font-size:13px;font-weight:800;padding:7px 14px;border-radius:999px;}
.pj-pestana:hover{color:var(--tinta);}
.pj-pestana.activa{background:#fff;color:var(--verde);box-shadow:0 1px 4px rgba(0,0,0,.1);}

.gm{flex:1;min-height:0;display:grid;grid-template-columns:minmax(0,1fr) 340px;}
.gm-centro{display:flex;flex-direction:column;min-width:0;min-height:0;border-right:1px solid var(--linea);}
.gm-mapa{position:relative;flex:1;min-height:320px;overflow:hidden;background:#F4F1EC;}
.gm-mapa canvas{position:absolute;inset:0;display:block;cursor:grab;touch-action:none;}
.gm-mapa canvas:active{cursor:grabbing;}
.gm-cargando{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;text-align:center;padding:20px;font-weight:700;color:var(--gris);background:rgba(244,241,236,.85);z-index:5;}
.gm-tip{position:absolute;z-index:6;pointer-events:none;background:rgba(63,53,48,.94);color:#fff;border-radius:8px;padding:6px 10px;font-size:12px;max-width:260px;box-shadow:0 4px 12px rgba(0,0,0,.2);}
.gm-tip b{display:block;font-size:12.5px;}
.gm-tip span{opacity:.85;}

.gm-controles{position:absolute;top:12px;left:12px;display:flex;flex-direction:column;gap:4px;z-index:4;}
.gm-controles button{width:32px;height:32px;border-radius:8px;background:#fff;color:var(--tinta);font-size:18px;font-weight:700;box-shadow:0 1px 5px rgba(0,0,0,.18);}
.gm-controles button:hover{background:var(--verde-suave);}
.gm-capas{position:absolute;top:12px;right:12px;z-index:4;display:flex;gap:10px;align-items:center;background:rgba(255,255,255,.95);border-radius:999px;padding:5px 12px;box-shadow:0 1px 5px rgba(0,0,0,.15);font-size:12px;font-weight:700;color:var(--gris);}
.gm-capas select{font:inherit;border:none;background:transparent;color:var(--tinta);font-weight:800;cursor:pointer;}
.gm-capas label{display:flex;align-items:center;gap:4px;cursor:pointer;}
.gm-leyenda{position:absolute;left:12px;bottom:12px;z-index:4;display:flex;flex-wrap:wrap;gap:4px 10px;max-width:calc(100% - 140px);background:rgba(255,255,255,.95);border-radius:10px;padding:6px 10px;box-shadow:0 1px 5px rgba(0,0,0,.15);font-size:11px;font-weight:700;color:var(--gris);}
.gm-leyenda span{display:flex;align-items:center;gap:4px;}
.gm-leyenda i,.gm-tomas i{display:inline-block;width:11px;height:11px;border-radius:3px;}
.c-regando{background:#1F5C8A;} .c-parcial{background:#D68C12;} .c-aplazado{background:#B3261E;} .c-parada{background:#455A64;} .c-inactivo{background:#E9E5E0;}
.c-reserva{background:#fff;border:2px solid #E0B400;}
.gm-leyenda b{display:inline-flex;align-items:center;justify-content:center;width:13px;height:13px;font-size:8px;color:#fff;}
.gm-leyenda .s-m{background:#5B3FA0;clip-path:polygon(25% 5%,75% 5%,100% 50%,75% 95%,25% 95%,0 50%);}
.gm-leyenda .s-l{background:#00796B;border-radius:2px;}
.gm-vivo{position:absolute;right:12px;bottom:12px;z-index:4;background:rgba(255,255,255,.95);border-radius:999px;padding:5px 10px;font-size:11px;font-weight:800;color:var(--verde);box-shadow:0 1px 5px rgba(0,0,0,.15);display:flex;align-items:center;gap:6px;}
.gm-vivo i{width:8px;height:8px;border-radius:50%;background:#2E8B57;box-shadow:0 0 0 0 rgba(46,139,87,.6);}
.gm-vivo.latido i{animation:gm-latido .9s ease-out;}
@keyframes gm-latido{0%{box-shadow:0 0 0 0 rgba(46,139,87,.7);}100%{box-shadow:0 0 0 10px rgba(46,139,87,0);}}

/* Ficha */
.gm-ficha{position:absolute;left:56px;top:12px;z-index:5;width:300px;max-height:calc(100% - 70px);overflow:auto;background:#fff;border-radius:12px;padding:14px 14px 12px;box-shadow:0 8px 28px rgba(0,0,0,.22);}
.gm-ficha-x{position:absolute;right:8px;top:6px;width:26px;height:26px;border-radius:50%;background:transparent;color:var(--gris);font-size:18px;}
.gm-ficha-x:hover{background:var(--crema);}
.gm-ficha-t{font-family:'Playfair Display',serif;font-weight:800;font-size:18px;line-height:1.2;padding-right:22px;}
.gm-ficha-s{font-size:12px;color:var(--gris);margin:3px 0 8px;}
.gm-ficha-e{display:inline-block;font-size:12px;font-weight:800;padding:4px 10px;border-radius:999px;color:#fff;margin-bottom:10px;}
.gm-ficha-e.c-inactivo{color:var(--tinta);}
.gm-fbs{display:flex;gap:6px;align-items:flex-end;height:64px;padding:4px 2px 0;}
.gm-fb{flex:1;display:flex;flex-direction:column;align-items:center;gap:2px;}
.gm-fb-col{position:relative;width:100%;height:46px;display:flex;align-items:flex-end;justify-content:center;}
.gm-fb-col i{position:absolute;bottom:0;width:62%;border-radius:3px 3px 0 0;}
.gm-fb-col i.as{background:#7FA6C4;}
.gm-fb-col i.as.p{background:#455A64;height:4px !important;}
.gm-fb-col i.ped{background:transparent;border:1.5px dashed #D68C12;border-bottom:none;}
.gm-fb-col i.re{width:80%;height:3px;background:#3F3530;border-radius:2px;}
.gm-fb.sel .gm-fb-col i.as{background:#1F5C8A;}
.gm-fb small{font-size:10px;font-weight:800;color:var(--gris);}
.gm-fb.sel small{color:var(--tinta);}
.gm-ficha-ley{display:flex;gap:8px;font-size:10.5px;color:var(--gris);margin:4px 0 8px;align-items:center;}
.gm-ficha-ley i{display:inline-block;width:10px;height:6px;border-radius:2px;margin-right:2px;}
.gm-ficha-ley i.as{background:#7FA6C4;} .gm-ficha-ley i.ped{border:1.5px dashed #D68C12;} .gm-ficha-ley i.re{background:#3F3530;height:3px;}
.gm-ficha-l{font-size:12.5px;padding:6px 0;border-top:1px solid var(--linea);}
.gm-ficha-l.gris{color:var(--gris);}
.gm-ficha .rojo{color:var(--rojo);}
.gm-ficha-tab{width:100%;font-size:12.5px;border-collapse:collapse;margin-top:4px;}
.gm-ficha-tab td{padding:4px 0;border-top:1px solid var(--linea);}
.gm-ficha-tab td:last-child{text-align:right;}
.gm-ficha-sim{margin-top:8px;width:100%;background:var(--crema);color:var(--tinta);font-size:12px;font-weight:800;padding:8px;border-radius:8px;}
.gm-ficha-sim:hover{background:var(--verde-suave);color:var(--verde);}

/* Línea de tiempo */
.gm-timeline{display:flex;align-items:center;gap:10px;padding:10px 14px;border-top:1px solid var(--linea);background:#fff;flex-shrink:0;}
.gm-play{width:40px;height:40px;border-radius:50%;background:var(--verde);color:#fff;font-size:14px;flex-shrink:0;}
.gm-play:hover{background:#26402c;}
.gm-vels{display:flex;background:var(--crema);border-radius:999px;padding:2px;flex-shrink:0;}
.gm-vel{background:transparent;color:var(--gris);font-size:11px;font-weight:800;padding:5px 8px;border-radius:999px;}
.gm-vel.activo{background:#fff;color:var(--verde);box-shadow:0 1px 3px rgba(0,0,0,.1);}
.gm-dias-wrap{flex:1;min-width:0;}
.gm-dias{display:grid;grid-template-columns:repeat(7,1fr);gap:4px;}
.gm-dia{background:var(--crema);border-radius:8px;padding:5px 2px;display:flex;flex-direction:column;align-items:center;line-height:1.2;border-bottom:3px solid transparent;color:var(--tinta);}
.gm-dia b{font-size:12px;}
.gm-dia span{font-size:10.5px;color:var(--gris);font-weight:700;}
.gm-dia.ok{border-bottom-color:#9fb8a5;} .gm-dia.deficit{border-bottom-color:#d9776f;}
.gm-dia.hoy b::after{content:' •';color:var(--verde);}
.gm-dia.activo{background:var(--verde);color:#fff;}
.gm-dia.activo span{color:rgba(255,255,255,.85);}
.gm-play-barra{height:3px;background:var(--crema);border-radius:3px;margin-top:6px;overflow:hidden;}
.gm-play-barra i{display:block;height:100%;width:0;background:var(--verde);border-radius:3px;transition:width .12s linear;}

/* Panel lateral */
.gm-lateral{overflow:auto;padding:14px 16px 20px;background:#FCFBF9;min-height:0;}
.gm-dia-cab{display:flex;justify-content:space-between;align-items:center;gap:6px;flex-wrap:wrap;}
.gm-dia-cab b{font-family:'Playfair Display',serif;font-size:20px;}
.gm-badge{font-size:10px;font-weight:800;padding:2px 7px;border-radius:999px;margin-left:6px;vertical-align:3px;}
.gm-badge.hoy{background:var(--verde-suave);color:var(--verde);}
.gm-badge.sim{background:#FFF4E0;color:#9A5B00;}
.gm-modo{display:flex;background:var(--crema);border-radius:999px;padding:2px;}
.gm-modo button{background:transparent;font-size:11px;font-weight:800;color:var(--gris);padding:4px 10px;border-radius:999px;}
.gm-modo button.activo{background:#fff;color:var(--verde);box-shadow:0 1px 3px rgba(0,0,0,.1);}
.gm-meteo{display:flex;flex-wrap:wrap;align-items:center;gap:4px 12px;font-size:18px;margin:10px 0 8px;}
.gm-meteo span{font-size:12px;color:var(--gris);}
.gm-meteo span b{font-size:15px;color:var(--tinta);}
.gm-meteo small{width:100%;font-size:10.5px;color:var(--gris);font-weight:600;}
.gm-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;}
.gm-kpis div{background:#fff;border:1px solid var(--linea);border-radius:10px;padding:7px 8px;}
.gm-kpis small{display:block;font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.05em;color:var(--gris);}
.gm-kpis b{font-size:19px;font-weight:800;color:var(--verde);font-variant-numeric:tabular-nums;}
.gm-kpis i{font-style:normal;font-size:10px;color:var(--gris);font-weight:700;margin-left:2px;}
.gm-kpis div.neg{background:var(--rojo-suave);border-color:#f2c3bd;} .gm-kpis div.neg b{color:var(--rojo);}
.gm-kpis em,.gm-resumen-sem em{display:block;font-style:normal;font-size:10.5px;font-weight:800;}
.gm-resumen-sem em{display:inline;}
em.mas{color:#B3261E;} em.menos{color:#2E7D32;}
.gm-tomas{display:flex;flex-wrap:wrap;gap:4px 12px;font-size:12px;font-weight:700;color:var(--gris);margin:9px 0 4px;}
.gm-tomas span{display:flex;align-items:center;gap:5px;}
.gm-sec-t{font-family:'Playfair Display',serif;font-weight:700;font-size:15px;margin:16px 0 6px;display:flex;align-items:baseline;gap:8px;}
.gm-sec-t span{font-family:'Mulish',sans-serif;font-size:11px;color:var(--gris);font-weight:600;}
.gm-graf{width:100%;max-width:400px;height:auto;display:block;}
.gm-graf-barra{cursor:pointer;}
.gm-resumen-sem{font-size:12px;color:var(--gris);margin-top:4px;line-height:1.5;}
.gm-resumen-sem b{color:var(--tinta);}

.gm-esc-f{display:block;margin-bottom:9px;font-size:12px;font-weight:700;color:var(--tinta);}
.gm-esc-f > span{display:block;margin-bottom:3px;}
.gm-esc-f select{font:inherit;font-size:12px;border:1px solid #d9d3cd;border-radius:6px;padding:2px 4px;background:#fff;}
.gm-esc-f input[type=range]{width:calc(100% - 64px);vertical-align:middle;accent-color:var(--verde);}
.gm-esc-f > b{display:inline-block;width:58px;text-align:right;font-size:12px;color:var(--verde);}
.gm-e-parar{display:flex;gap:4px;}
.gm-e-parar select{min-width:0;flex:1;}
.gm-e-padd{background:var(--verde-suave);color:var(--verde);font-size:11px;font-weight:800;padding:3px 8px;border-radius:6px;}
.gm-e-chips{display:flex;flex-wrap:wrap;gap:4px;margin-top:5px;}
.gm-e-chips span{background:#455A64;color:#fff;font-size:11px;font-weight:700;padding:2px 4px 2px 8px;border-radius:999px;display:flex;align-items:center;gap:2px;}
.gm-e-chips button{background:transparent;color:#fff;font-size:13px;width:18px;height:18px;border-radius:50%;}
.gm-check{display:flex;gap:6px;align-items:flex-start;font-size:12px;font-weight:600;color:var(--tinta);margin:4px 0 8px;cursor:pointer;}
.gm-e-reset{width:100%;background:var(--crema);color:var(--tinta);font-size:12px;font-weight:800;padding:7px;border-radius:8px;}
.gm-e-reset:not(:disabled):hover{background:#FFF4E0;color:#9A5B00;}

.pj .gm-alerta{display:flex;gap:8px;align-items:flex-start;width:100%;text-align:left;background:#fff;border:1px solid var(--linea);border-left:4px solid #b9b1aa;border-radius:8px;padding:7px 9px;margin-bottom:5px;}
.gm-alerta:hover{background:#F7F9F7;}
.pj .gm-alerta.n3{border-left-color:#B3261E;} .pj .gm-alerta.n2{border-left-color:#D68C12;} .pj .gm-alerta.n1{border-left-color:#1F5C8A;}
.gm-alerta > span{font-size:15px;line-height:1.2;}
.gm-alerta b{display:block;font-size:12px;color:var(--tinta);}
.gm-alerta small{display:block;font-size:11.5px;color:var(--gris);line-height:1.35;margin-top:1px;}
.gm-vacio-alertas{font-size:12px;color:var(--gris);padding:6px 0;}
.gm-fuentes{font-size:10.5px;color:#a49b94;margin-top:14px;line-height:1.5;}

@media (max-width:1000px){
  /* Apilado: mapa arriba y panel debajo; se desplaza toda la vista junta */
  .gm{grid-template-columns:1fr;grid-template-rows:auto auto;overflow:auto;}
  .gm-centro{border-right:none;}
  .gm-mapa{flex:none;height:460px;}
  .gm-lateral{overflow:visible;max-height:none;}
  .gm-ficha{left:12px;right:12px;width:auto;top:56px;}
}

.pj-atipico{color:#B3261E !important;}
.pj-kpi-aviso .pj-kpi-n{color:#9A5B00;font-weight:700;}
/* Reservas: caudal pedido frente al histórico */
.pj-umbral{display:flex;flex-wrap:wrap;align-items:center;gap:6px 10px;padding:10px 14px;border-bottom:1px solid var(--linea);font-size:13px;font-weight:700;}
.pj-input-umbral{width:70px;padding:5px 6px;border:1px solid #d9d3cd;border-radius:6px;font:inherit;font-weight:800;text-align:center;}
.pj-input-umbral:focus{outline:none;border-color:var(--verde);box-shadow:0 0 0 2px rgba(51,81,58,.15);}
.pj-deficit-txt{color:var(--rojo);}
.pj-tabla-reservas{min-width:720px;}
.pj-c-desv{box-shadow:inset 0 0 0 2px #B3261E;}
.pj-ley.pj-ley-desv{background:#fff;box-shadow:inset 0 0 0 2px #B3261E;}
.gm-meteo span{white-space:nowrap;}

descriptor.controllerScript:
/*
 * ============================================================================
 *  PROYECCIÓN SEMANAL DE DEMANDA Y REPARTO -- Gemelo digital (Solución G06)
 * ============================================================================
 *  Para cada Grupo_Riego y cada día de la semana (lunes a domingo):
 *
 *    Caudal previsto = Caudal base × Corrector de calor − Lluvia efectiva
 *
 *  - Caudal base: media de los días con riego de las últimas 4 semanas
 *    (caudal_manual si existe ese día; si no, caudal_fijado). Si no hay
 *    suficientes días, se usa la misma época de la campaña anterior.
 *  - Estados A/R/P (punto 3.1.1 de la propuesta): la toma que viene regando
 *    sigue Activa hasta que tenga una Parada (P); una Reserva (R) la activa
 *    desde ese día.
 *  - El agua se pide los jueves para la semana siguiente: cada Reserva del
 *    calendario (Zona regable) lleva el caudal pedido. La demanda usa ese
 *    caudal; el previsto por histórico se calcula igual y se muestra al lado.
 *    Si la reserva se desvía del histórico más que el umbral (editable desde
 *    el panel, atributo "umbral_aviso_reserva"), se avisa.
 *  - Las sondas de humedad NO intervienen en el cálculo (no todas las
 *    parcelas tienen sonda).
 *  - Corrector de calor: ET0 prevista / ET0 normal de esas fechas (media de
 *    los 3 años anteriores), limitado entre 0,7 y 1,3. Datos de Open-Meteo.
 *  - Lluvia efectiva: 75 % de la lluvia de los días con 5 mm o más,
 *    convertida a L/s con la superficie de la toma (mm × 10 × ha = m³).
 *
 *  Reparto (punto 3.2): con el caudal disponible que introduce el técnico
 *  para cada día, se asigna por prioridad (turnos en curso, después
 *  peticiones por orden de llegada), ajustando combinaciones al disponible.
 *  Si sobra agua se proponen adelantos de turnos y llenado de balsas. El
 *  técnico revisa y aprueba: el sistema no cambia nada en campo.
 *
 *  Se guarda en el activo CRBG_Resumen_Caudales:
 *    - telemetría "proyeccion_semana" (lunes 00:00): proyección fijada
 *    - atributo "caudal_disponible_<lunes>": disponible por día (L/s)
 *    - atributo "reparto_aprobado_<lunes>": reparto aprobado por el técnico
 *    - atributo "umbral_aviso_reserva": % de desviación reserva/histórico
 * ============================================================================
 */

/* =========================== NÚCLEO DE CÁLCULO ============================ */
/* Funciones puras (sin ThingsBoard ni DOM) para poder probarlas aparte.     */

var PJ = {
    DIAS: ['Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb', 'Dom'],
    DIAS_LARGO: ['Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado', 'Domingo'],
    UMBRAL_RIEGO_LS: 1,          // por debajo de esto un día cuenta como "no regó"
    MIN_DIAS_HISTORICO: 3,       // días con riego mínimos para fiarse de la media reciente
    PESO_RECIENTE: 0.7,          // mezcla reciente / campaña anterior cuando hay ambas
    K_MIN: 0.7, K_MAX: 1.3,      // límites del corrector de calor
    LLUVIA_MIN_MM: 5,            // por debajo, la lluvia no se considera efectiva
    LLUVIA_EFECTIVA: 0.75,       // fracción aprovechable de la lluvia
    MIN_PARCIAL: 0.5,            // reparto: un turno con prioridad acepta un parcial si recibe al menos esta fracción
    UMBRAL_RESERVA_PCT: 30,      // aviso si el caudal reservado se desvía del histórico más de este % (editable)
    PATRON_BALSA: /^Presa[\s-]|\(BALSA\)\s*$/i
};

// 'AAAA-MM-DD' en hora de Madrid
PJ._fmtFecha = null;
PJ.fecha = function (ts) {
    // El formateador se crea una sola vez: crearlo en cada llamada es muy lento
    if (!PJ._fmtFecha) PJ._fmtFecha = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Madrid', year: 'numeric', month: '2-digit', day: '2-digit' });
    return PJ._fmtFecha.format(new Date(ts));
};
// Lunes (00:00 local) de la semana de ts
PJ.lunesDe = function (ts) {
    var d = new Date(ts);
    var dow = (d.getDay() + 6) % 7; // 0 = lunes
    return new Date(d.getFullYear(), d.getMonth(), d.getDate() - dow).getTime();
};
PJ.sumarDias = function (ts, n) {
    var d = new Date(ts);
    return new Date(d.getFullYear(), d.getMonth(), d.getDate() + n).getTime();
};
PJ.fechasSemana = function (lunesTs) {
    var out = [];
    for (var i = 0; i < 7; i++) out.push(PJ.fecha(PJ.sumarDias(lunesTs, i) + 12 * 3600000));
    return out;
};
PJ.r1 = function (x) { return Math.round(x * 10) / 10; };
PJ.media = function (arr) {
    if (!arr.length) return null;
    var s = 0; arr.forEach(function (v) { s += v; }); return s / arr.length;
};
PJ.mediana = function (arr) {
    if (!arr.length) return null;
    var a = arr.slice().sort(function (x, y) { return x - y; });
    var m = Math.floor(a.length / 2);
    return a.length % 2 ? a[m] : (a[m - 1] + a[m]) / 2;
};

/*
 * Caudal diario real a partir de la telemetría: caudal_manual (media del día)
 * tiene prioridad sobre caudal_fijado (último valor del día), igual que el
 * Calendario. Devuelve { 'AAAA-MM-DD': L/s }.
 */
PJ.caudalPorDia = function (fijados, manuales) {
    var out = {}, ultimoTs = {};
    (fijados || []).forEach(function (p) {
        var v = parseFloat(p.value); if (isNaN(v)) return;
        var f = PJ.fecha(p.ts);
        if (ultimoTs[f] === undefined || p.ts > ultimoTs[f]) { ultimoTs[f] = p.ts; out[f] = v; }
    });
    var acc = {};
    (manuales || []).forEach(function (p) {
        var v = parseFloat(p.value); if (isNaN(v)) return;
        var f = PJ.fecha(p.ts);
        if (!acc[f]) acc[f] = { s: 0, n: 0 };
        acc[f].s += v; acc[f].n++;
    });
    Object.keys(acc).forEach(function (f) { out[f] = acc[f].s / acc[f].n; });
    return out;
};

/*
 * Caudal base de una toma (L/s en un día de riego).
 *   porDia: { fecha: L/s } del histórico reciente
 *   fechasRecientes: fechas a mirar (últimas 4 semanas antes del lunes)
 *   porDiaAnterior / fechasAnteriores: misma época de la campaña anterior
 */
PJ.caudalBase = function (porDia, fechasRecientes, porDiaAnterior, fechasAnteriores) {
    function riegos(mapa, fechas) {
        var v = [];
        (fechas || []).forEach(function (f) {
            if (mapa && mapa[f] !== undefined && mapa[f] > PJ.UMBRAL_RIEGO_LS) v.push(mapa[f]);
        });
        return v;
    }
    var rec = riegos(porDia, fechasRecientes);
    var ant = riegos(porDiaAnterior, fechasAnteriores);
    // Mediana y no media: un pico puntual del caudalímetro no dispara la base
    var mRec = rec.length >= PJ.MIN_DIAS_HISTORICO ? PJ.mediana(rec) : null;
    var mAnt = ant.length >= PJ.MIN_DIAS_HISTORICO ? PJ.mediana(ant) : null;
    if (mRec !== null && mAnt !== null) {
        return { base: PJ.PESO_RECIENTE * mRec + (1 - PJ.PESO_RECIENTE) * mAnt, fuente: 'reciente+anterior', diasRiego: rec.length };
    }
    if (mRec !== null) return { base: mRec, fuente: 'reciente', diasRiego: rec.length };
    if (mAnt !== null) return { base: mAnt, fuente: 'campaña anterior', diasRiego: ant.length };
    // Pocos datos: lo que haya, marcado como poco fiable
    var todo = rec.concat(ant);
    if (todo.length) return { base: PJ.mediana(todo), fuente: 'pocos datos', diasRiego: todo.length };
    return { base: null, fuente: 'sin histórico', diasRiego: 0 };
};

/*
 * Caudal base atípico: más de 5 L/s por hectárea (lo normal es en torno a
 * 1 L/s/ha) o más de 2000 L/s. Suele ser un dato erróneo del caudalímetro o
 * una superficie mal puesta. No se corrige solo: se marca para revisarlo.
 */
PJ.ATIPICO_LS_HA = 5;
PJ.textoDesviacion = function (dv) {
    if (!dv) return '';
    if (dv.lluvia) return 'con lluvia prevista';
    return (dv.pct > 0 ? '+' : '') + Math.round(dv.pct).toLocaleString('es-ES') + ' %';
};
PJ.esAtipico = function (base, superficie) {
    if (!(base > 0)) return false;
    if (base > 2000) return true;
    return !!(superficie && base / superficie > PJ.ATIPICO_LS_HA);
};

/*
 * ¿Venía regando al empezar la semana? Sí si regó alguno de los 2 días
 * anteriores al lunes y el último de ellos no tiene Parada.
 */
PJ.activoAlInicio = function (porDia, fechasPrevias2, marcas) {
    var ultimo = fechasPrevias2[fechasPrevias2.length - 1];
    if (marcas && marcas[ultimo] && marcas[ultimo].P) return false;
    return fechasPrevias2.some(function (f) {
        return porDia && porDia[f] !== undefined && porDia[f] > PJ.UMBRAL_RIEGO_LS;
    });
};

/* Corrector de calor y lluvia de un día */
PJ.corrector = function (et0, et0Normal) {
    if (et0 === null || et0 === undefined || !et0Normal) return 1;
    return Math.max(PJ.K_MIN, Math.min(PJ.K_MAX, et0 / et0Normal));
};
PJ.lluviaEfectivaMm = function (mm) {
    if (mm === null || mm === undefined || mm < PJ.LLUVIA_MIN_MM) return 0;
    return mm * PJ.LLUVIA_EFECTIVA;
};
// mm sobre ha -> L/s equivalentes repartidos en 24 h (1 mm/ha = 10 m³)
PJ.lluviaLs = function (mmEfectivos, ha) {
    return mmEfectivos * 10 * ha * 1000 / 86400;
};

/*
 * Caudal previsto por el histórico para un día: base × corrector de calor −
 * lluvia efectiva. Devuelve { q, k, lluviaLs } o null si no hay base.
 */
PJ.previstoHistorico = function (base, superficie, met) {
    if (base === null || base === undefined) return null;
    met = met || {};
    var k = PJ.corrector(met.et0, met.et0Normal);
    var mmEf = PJ.lluviaEfectivaMm(met.lluvia);
    if (superficie) {
        var lls = PJ.lluviaLs(mmEf, superficie);
        return { q: Math.max(0, base * k - lls), k: k, lluviaLs: lls };
    }
    // Sin superficie: la lluvia reduce en proporción a la ET0 del día
    var frac = (met.et0 && met.et0 > 0) ? Math.min(1, mmEf / met.et0) : (mmEf > 0 ? 1 : 0);
    return { q: Math.max(0, base * k * (1 - frac)), k: k, lluviaLs: 0 };
};

/*
 * Proyección de los 7 días de una toma.
 *   g: { base, activoInicio, superficie, marcas: { fecha: {R, P, pet:{caudal, pedidoEn}} } }
 *   fechas: 7 fechas de la semana
 *   meteo: 7 x { et0, et0Normal, lluvia }
 *   baseSector: base de reserva (mediana del sector) si la toma no tiene histórico
 * Devuelve 7 x { q, qHist, motivo, R, P, k, lluviaLs, pedido, pedidoEn, sinCaudal }
 *   q: demanda del día (caudal reservado si lo hay; si no, el histórico)
 *   qHist: lo que daría el histórico ese día (para comparar con la reserva)
 */
PJ.proyectarToma = function (g, fechas, meteo, baseSector) {
    var activo = !!g.activoInicio;
    var caudalPedidoTurno = null;   // si el turno empezó con un caudal pedido, se mantiene
    var pedidoEnTurno = null;
    var dias = [];
    var tieneBase = g.base !== null && g.base !== undefined;
    var base = tieneBase ? g.base : baseSector;
    for (var i = 0; i < 7; i++) {
        var f = fechas[i];
        var m = (g.marcas && g.marcas[f]) || {};
        var d = { q: 0, qHist: null, motivo: 'inactivo', R: !!m.R, P: !!m.P, k: 1, lluviaLs: 0, pedido: null, pedidoEn: null, sinCaudal: false };
        if (m.P) {
            activo = false; caudalPedidoTurno = null; pedidoEnTurno = null;
            d.motivo = 'parada';
        } else {
            if (m.R) {
                activo = true;
                // Caudal 0 o vacío = reserva sin caudal (el calendario la pinta como una R normal)
                caudalPedidoTurno = (m.pet && m.pet.caudal !== null && m.pet.caudal !== undefined && m.pet.caudal !== '' && !isNaN(m.pet.caudal) && Number(m.pet.caudal) > 0) ? Number(m.pet.caudal) : null;
                pedidoEnTurno = (m.pet && m.pet.pedidoEn) ? Number(m.pet.pedidoEn) : null;
                d.sinCaudal = caudalPedidoTurno === null;   // reserva antigua, sin caudal indicado
            }
            if (activo) {
                var h = PJ.previstoHistorico(base, g.superficie, meteo[i]);
                if (h) { d.qHist = PJ.r1(h.q); d.k = h.k; d.lluviaLs = h.lluviaLs; }
                if (caudalPedidoTurno !== null) {
                    // Caudal reservado en el calendario: es la demanda de ese día
                    d.q = caudalPedidoTurno; d.motivo = 'reservado'; d.pedido = caudalPedidoTurno;
                } else if (h) {
                    d.q = h.q; d.motivo = tieneBase ? 'histórico' : 'estimado sector';
                } else {
                    d.q = 0; d.motivo = 'sin histórico';
                }
                d.pedidoEn = pedidoEnTurno;
            }
        }
        d.q = PJ.r1(d.q);
        dias.push(d);
    }
    return dias;
};

/*
 * Desviación del caudal reservado respecto al histórico de ese día.
 * Devuelve null si no hay reserva con caudal o no hay histórico con el que
 * comparar; si no, { pct, fuera, tipo: 'mas'|'menos' } (fuera = supera umbral).
 * Si el histórico es 0 por lluvia y la reserva pide agua: { pct: null,
 * fuera: true, lluvia: true }.
 */
PJ.desviacionReserva = function (d, umbralPct) {
    if (!d || d.pedido === null || d.pedido === undefined || d.qHist === null || d.qHist === undefined) return null;
    // Con lluvia el histórico puede quedar en 0: no hay % posible, pero si
    // la toma pide agua ese día se avisa igualmente.
    if (!(d.qHist > 0)) return d.pedido > PJ.UMBRAL_RIEGO_LS ? { pct: null, fuera: true, tipo: 'mas', lluvia: true } : null;
    var pct = (d.pedido - d.qHist) / d.qHist * 100;
    var u = (umbralPct === null || umbralPct === undefined || isNaN(umbralPct)) ? PJ.UMBRAL_RESERVA_PCT : umbralPct;
    return { pct: pct, fuera: Math.abs(pct) > u, tipo: pct > 0 ? 'mas' : 'menos' };
};

/*
 * Reparto de un día.
 *   demandas: [{ id, nombre, q, enCurso, pedidoEn, diaPeticion }]
 *   disponible: L/s (null = sin límite, se asigna todo)
 * Prioridad (punto 3.2): 1) turnos en curso (estabilidad del flujo),
 * 2) peticiones por orden de llegada. Se asigna en ese orden; si a una no le
 * cabe entera, recibe lo que queda si es al menos la mitad de lo que pide.
 * Si queda menos, se buscan peticiones posteriores que quepan enteras y lo
 * último que sobre va a la primera que se saltó, para no dejar agua sin usar.
 * Devuelve { asignado: {id: L/s}, estado: {id: 'completo'|'parcial'|'aplazado'},
 *            demanda, disponible, sobrante, deficit }
 */
PJ.repartirDia = function (demandas, disponible) {
    var lista = demandas.filter(function (x) { return x.q > 0; });
    var demanda = 0; lista.forEach(function (x) { demanda += x.q; });
    var asignado = {}, estado = {};
    if (disponible === null || disponible === undefined || isNaN(disponible) || demanda <= disponible) {
        lista.forEach(function (x) { asignado[x.id] = x.q; estado[x.id] = 'completo'; });
        return { asignado: asignado, estado: estado, demanda: PJ.r1(demanda), disponible: disponible,
                 sobrante: (disponible === null || disponible === undefined || isNaN(disponible)) ? null : PJ.r1(disponible - demanda), deficit: 0 };
    }
    lista.sort(function (a, b) {
        if (a.enCurso !== b.enCurso) return a.enCurso ? -1 : 1;
        var pa = (a.pedidoEn !== null && a.pedidoEn !== undefined) ? a.pedidoEn : -Infinity; // R antiguas sin hora: primero
        var pb = (b.pedidoEn !== null && b.pedidoEn !== undefined) ? b.pedidoEn : -Infinity;
        if (pa !== pb) return pa - pb;
        return String(a.nombre).localeCompare(String(b.nombre), 'es');
    });
    // Orden estricto de prioridad: quien va antes recibe lo que quede (parcial)
    // si es al menos la mitad de lo que pide; solo si queda menos se pasa a
    // las peticiones posteriores que sí caben enteras ("ajuste de
    // combinaciones"), y lo último que sobre va al primero que se saltó.
    var resto = disponible;
    var saltados = [];
    lista.forEach(function (x) {
        if (resto <= 1e-9) { asignado[x.id] = 0; estado[x.id] = 'aplazado'; return; }
        if (x.q <= resto + 1e-9) { asignado[x.id] = x.q; estado[x.id] = 'completo'; resto -= x.q; return; }
        if (resto >= PJ.MIN_PARCIAL * x.q && resto > PJ.UMBRAL_RIEGO_LS) {
            asignado[x.id] = PJ.r1(resto); estado[x.id] = 'parcial'; resto = 0; return;
        }
        saltados.push(x);
    });
    saltados.forEach(function (x, i) {
        if (i === 0 && resto > PJ.UMBRAL_RIEGO_LS) {
            asignado[x.id] = PJ.r1(resto); estado[x.id] = 'parcial'; resto = 0;
        } else {
            asignado[x.id] = 0; estado[x.id] = 'aplazado';
        }
    });
    return { asignado: asignado, estado: estado, demanda: PJ.r1(demanda), disponible: disponible,
