};

/*
 * Propuestas cuando sobra agua un día (punto 3.2):
 *   - adelantos: tomas con Reserva para un día posterior de la semana que
 *     no riegan este día y cuyo caudal cabe en el sobrante (por orden de llegada)
 *   - balsas: grupos de balsa/presa que no riegan este día
 */
PJ.propuestasExcedente = function (grupos, iDia, sobrante) {
    var adelantos = [], balsas = [];
    if (!(sobrante > PJ.UMBRAL_RIEGO_LS)) return { adelantos: adelantos, balsas: balsas };
    var resto = sobrante;
    var candidatos = [];
    grupos.forEach(function (g) {
        if (!g.dias || g.dias[iDia].q > 0) return;
        for (var j = iDia + 1; j < 7; j++) {
            if (g.dias[j].R && g.dias[j].q > 0) {
                candidatos.push({ g: g, diaPeticion: j, q: g.dias[j].q, pedidoEn: g.dias[j].pedidoEn });
                break;
            }
        }
    });
    candidatos.sort(function (a, b) {
        var pa = a.pedidoEn !== null && a.pedidoEn !== undefined ? a.pedidoEn : -Infinity;
        var pb = b.pedidoEn !== null && b.pedidoEn !== undefined ? b.pedidoEn : -Infinity;
        return pa - pb;
    });
    candidatos.forEach(function (c) {
        if (c.q <= resto) { adelantos.push(c); resto -= c.q; }
    });
    grupos.forEach(function (g) {
        if (PJ.PATRON_BALSA.test(g.nombre || '') && (!g.dias || g.dias[iDia].q === 0)) balsas.push(g);
    });
    return { adelantos: adelantos, balsas: balsas, restoTrasAdelantos: PJ.r1(resto) };
};

