/*
 * Semana completa: proyección de todas las tomas + reparto día a día.
 * Función pura: sirve para el cálculo real y para los escenarios del gemelo
 * ("¿y si…?"), que nunca se guardan.
 *   grupos: [{ id, nombre, sector, base, superficie, marcas, activoInicio }]
 *   fechas: 7 fechas · meteoDe(g): 7 días de meteo · disponible: 7 x L/s|null
 *   esc (opcional): { lluviaExtra: {dia, mm}, calorPct, disponiblePct,
 *                     paradas: [{id, dia}], desdeDia }
 *   desdeDia: el escenario solo cambia ese día y los siguientes (lo ya
 *   pasado no se simula). Por defecto 0.
 * Devuelve { dias: {id: 7 x d}, reparto: 7 x r, disponible: 7 x L/s|null }
 */
PJ.calcularSemana = function (grupos, fechas, meteoDe, disponible, esc) {
    esc = esc || {};
    var desde = esc.desdeDia || 0;
    var basesSector = {};
    grupos.forEach(function (g) {
        if (g.base !== null && g.base !== undefined) (basesSector[g.sector] = basesSector[g.sector] || []).push(g.base);
    });
    var paradasEsc = {};
    (esc.paradas || []).forEach(function (p) { (paradasEsc[p.id] = paradasEsc[p.id] || {})[p.dia] = true; });
    var dias = {};
    grupos.forEach(function (g) {
        var met = (meteoDe(g) || []).map(function (m, i) {
            var c = { et0: m.et0, et0Normal: m.et0Normal, lluvia: m.lluvia, tmax: m.tmax };
            if (i >= desde && esc.calorPct && c.et0 !== null && c.et0 !== undefined) c.et0 = c.et0 * (1 + esc.calorPct / 100);
            if (esc.lluviaExtra && esc.lluviaExtra.dia === i && i >= desde) c.lluvia = (c.lluvia || 0) + esc.lluviaExtra.mm;
            return c;
        });
        var marcas = g.marcas;
        if (paradasEsc[g.id]) {
            marcas = {};
            Object.keys(g.marcas || {}).forEach(function (f) { marcas[f] = g.marcas[f]; });
            Object.keys(paradasEsc[g.id]).forEach(function (i) {
                var f = fechas[Math.max(Number(i), desde)];
                marcas[f] = { P: true };
            });
        }
        var gg = { base: g.base, activoInicio: g.activoInicio, superficie: g.superficie, marcas: marcas };
        dias[g.id] = PJ.proyectarToma(gg, fechas, met, PJ.mediana(basesSector[g.sector] || []));
    });
    var disp = disponible.map(function (v, i) {
        return (v === null || v === undefined) ? null : (esc.disponiblePct && i >= desde ? v * (1 + esc.disponiblePct / 100) : v);
    });
    var reparto = [];
    var asignadoAyer = {};
    grupos.forEach(function (g) { if (g.activoInicio) asignadoAyer[g.id] = true; });
    for (var i = 0; i < 7; i++) {
        var demandas = grupos.map(function (g) {
            var d = dias[g.id][i];
            return { id: g.id, nombre: g.nombre, q: d.q, enCurso: !!asignadoAyer[g.id] && !d.R, pedidoEn: d.pedidoEn };
        });
        var r = PJ.repartirDia(demandas, disp[i]);
        r.propuestas = PJ.propuestasExcedente(grupos.map(function (g) { return { id: g.id, nombre: g.nombre, dias: dias[g.id] }; }), i, r.sobrante);
        reparto.push(r);
        asignadoAyer = {};
        Object.keys(r.asignado).forEach(function (id) { if (r.asignado[id] > 0) asignadoAyer[id] = true; });
    }
    return { dias: dias, reparto: reparto, disponible: disp };
};

/*
 * Control de sobreconsumos (punto 3.2): compara el caudal real con el
 * asignado. Aviso si se pasa hoy; alerta si se pasa de forma continuada
 * (también ayer). Tolerancia: 15 % y al menos 2 L/s.
 *   real: 7 x L/s|null · asignado: 7 x L/s · iHoy: índice del día de hoy
 */
PJ.TOLERANCIA_SOBRECONSUMO = 0.15;
PJ.sobreconsumo = function (real, asignado, iHoy) {
    function pasa(i) {
        if (i < 0 || real[i] === null || real[i] === undefined || asignado[i] === null || asignado[i] === undefined) return false;
        return real[i] > asignado[i] * (1 + PJ.TOLERANCIA_SOBRECONSUMO) + 2;
    }
    if (!pasa(iHoy)) return null;
    return { nivel: pasa(iHoy - 1) ? 'alerta' : 'aviso', real: real[iHoy], asignado: asignado[iHoy],
             exceso: PJ.r1(real[iHoy] - asignado[iHoy]) };
};

/* ---------- Geometría ---------- */
// Lee la geometría de ThingsBoard en sus formatos habituales y devuelve una
// lista de anillos [[lat, lng], ...]. Admite [[lat,lng]], [[[lat,lng]]],
// GeoJSON (Polygon / MultiPolygon, en lng,lat) y WKT POLYGON/MULTIPOLYGON.
PJ.parseGeometria = function (valor) {
    if (valor === null || valor === undefined || valor === '') return [];
    var v = valor;
    if (typeof v === 'string') {
        var t = v.trim();
        if (/^(MULTI)?POLYGON/i.test(t)) {
            var anillosW = [];
            (t.match(/\(\s*[-\d.]+\s+[-\d.]+[^()]*\)/g) || []).forEach(function (grupo) {
                var pts = grupo.replace(/[()]/g, '').split(',').map(function (p) {
                    var xy = p.trim().split(/\s+/).map(Number); return [xy[1], xy[0]];
                });
                if (pts.length >= 3) anillosW.push(pts);
            });
            return anillosW;
        }
        try { v = JSON.parse(t); } catch (e) { return []; }
    }
    if (v && v.type && v.coordinates) {
        var polys = v.type === 'MultiPolygon' ? v.coordinates : (v.type === 'Polygon' ? [v.coordinates] : []);
        var out = [];
        polys.forEach(function (poly) { if (poly[0]) out.push(poly[0].map(function (p) { return [p[1], p[0]]; })); });
        return out;
    }
    if (v && v.type === 'Feature' && v.geometry) return PJ.parseGeometria(v.geometry);
    if (!Array.isArray(v)) return [];
    var anillos = [];
    (function bajar(a) {
        if (!Array.isArray(a) || !a.length) return;
        if (typeof a[0] === 'number') return;
        if (Array.isArray(a[0]) && typeof a[0][0] === 'number') { anillos.push(a); return; }
        a.forEach(bajar);
    })(v);
    // Orden de las coordenadas: en Andalucía lat ≈ 36–39 y lng ≈ -7 – -2
    return anillos.map(function (r) {
        var p = r[0];
        var invertido = Math.abs(p[0]) < 10 && Math.abs(p[1]) > 30;
        return r.map(function (q) { return invertido ? [Number(q[1]), Number(q[0])] : [Number(q[0]), Number(q[1])]; });
    }).filter(function (r) { return r.length >= 3; });
};
PJ.centroide = function (anillos) {
    var sLat = 0, sLng = 0, n = 0;
    (anillos || []).forEach(function (r) { r.forEach(function (p) { sLat += p[0]; sLng += p[1]; n++; }); });
    return n ? [sLat / n, sLng / n] : null;
};
PJ.puntoEnPoligono = function (lat, lng, anillos) {
    var dentro = false;
    (anillos || []).forEach(function (r) {
        for (var i = 0, j = r.length - 1; i < r.length; j = i++) {
            var yi = r[i][0], xi = r[i][1], yj = r[j][0], xj = r[j][1];
            if (((yi > lat) !== (yj > lat)) && (lng < (xj - xi) * (lat - yi) / (yj - yi) + xi)) dentro = !dentro;
        }
    });
    return dentro;
};
PJ.distanciaKm = function (a, b) {
    var R = 6371, dLat = (b[0] - a[0]) * Math.PI / 180, dLng = (b[1] - a[1]) * Math.PI / 180;
    var s = Math.sin(dLat / 2) * Math.sin(dLat / 2) + Math.cos(a[0] * Math.PI / 180) * Math.cos(b[0] * Math.PI / 180) * Math.sin(dLng / 2) * Math.sin(dLng / 2);
    return 2 * R * Math.atan2(Math.sqrt(s), Math.sqrt(1 - s));
};

