    function cargarCapas() {
        var campos = [{ type: 'ENTITY_FIELD', key: 'name' }, { type: 'ENTITY_FIELD', key: 'label' }];
        var pGrupos = consulta({ type: 'assetType', assetTypes: [api.perfilNombre], assetNameFilter: '' }, campos,
            [{ type: 'ATTRIBUTE', key: 'geometry' }, { type: 'TIME_SERIES', key: 'media_proyectada' }, { type: 'TIME_SERIES', key: 'caudal_Sum' }])
            .catch(function () { return []; });
        var pSectores = consulta({ type: 'assetType', assetTypes: ['Sector'], assetNameFilter: '' }, campos,
            [{ type: 'ATTRIBUTE', key: 'geometry' }]).catch(function () { return []; });
        var tiposSensor = ['Estacion meteorologica', 'Estacion agroclimatica', 'Lisimetro', 'Liximetro'];
        var pSensores = consulta({ type: 'deviceType', deviceTypes: tiposSensor, deviceType: tiposSensor[0], deviceNameFilter: '' },
            campos.concat([{ type: 'ENTITY_FIELD', key: 'type' }]),
            ['latitude', 'longitude', 'zona', 'cultivo', 'finca'].map(function (k) { return { type: 'ATTRIBUTE', key: k }; }).concat(
            ['eto_pm', 'weather_sumrain', 'weather_tmax', 'ExtTemp', 'rain_1',
             'irrigsumday', 'drenaje_lm2', 'cva_30', 'cva_60', 'cva_90'].map(function (k) { return { type: 'TIME_SERIES', key: k }; })))
            .catch(function () { return []; });
        return Promise.all([pGrupos, pSectores, pSensores]).then(function (r) {
            // Grupos: geometría y valor en vivo
            var porId = {};
            r[0].forEach(function (e) { porId[e.entityId.id] = e; });
            estado.grupos.forEach(function (g) {
                var e = porId[g.id];
                g.anillos = e ? PJ.parseGeometria(val(e, 'ATTRIBUTE', 'geometry')) : [];
                g.centro = PJ.centroide(g.anillos);
                if (e) actualizarVivo(g, e);
            });
            // Sectores
            G.sectores = r[1].map(function (e) {
                var nom = val(e, 'ENTITY_FIELD', 'name') || '';
                var m = String(nom).match(/(\d+)/);
                var an = PJ.parseGeometria(val(e, 'ATTRIBUTE', 'geometry'));
                return { id: e.entityId.id, nombre: nom, num: m ? Number(m[1]) : null, anillos: an, centro: PJ.centroide(an) };
            }).filter(function (x) { return x.anillos.length; });
            // Grupos sin geometría: alrededor del centro de su sector
            var sinGeo = estado.grupos.filter(function (g) { return !g.centro; });
            sinGeo.forEach(function (g, i) {
                var sec = G.sectores.find(function (x) { return x.num === g.sector; });
                var base = sec ? sec.centro : null;
                if (base) {
                    var ang = i * 2.39996, rad = 0.004 * Math.sqrt(i + 1);
                    g.centro = [base[0] + rad * Math.sin(ang), base[1] + rad * 1.25 * Math.cos(ang)];
