            G.sensores = r[2].map(function (e) {
                var tipo = (val(e, 'ENTITY_FIELD', 'type') || '').toLowerCase();
                var lat = num(val(e, 'ATTRIBUTE', 'latitude')), lng = num(val(e, 'ATTRIBUTE', 'longitude'));
                var cls = (tipo.indexOf('lis') > -1 || tipo.indexOf('lix') > -1) ? 'lisimetro' : (tipo.indexOf('sonda') > -1 ? 'humedad' : 'meteo');
                var v = {};
                ['eto_pm', 'weather_sumrain', 'weather_tmax', 'ExtTemp', 'rain_1',
                 'irrigsumday', 'drenaje_lm2', 'cva_30', 'cva_60', 'cva_90'].forEach(function (k) {
                    var x = num(val(e, 'TIME_SERIES', k)); if (x !== null) v[k] = { v: x, ts: tsDe(e, 'TIME_SERIES', k) };
