    // ETo y lluvia MEDIDAS por las estaciones propias: sustituyen a la
    // previsión en los días ya pasados y hoy, en el sector de cada estación.
    function meteoEstaciones() {
        var est = G.sensores.filter(function (x) { return x.tipo === 'meteo'; });
        if (!est.length) return Promise.resolve();
        var fechas = PJ.fechasSemana(estado.lunes), hoy = PJ.fecha(Date.now());
        var hasta = Math.min(Date.now(), PJ.sumarDias(estado.lunes, 7) - 1);
        if (hasta < estado.lunes) return Promise.resolve();
        return Promise.all(est.map(function (x) {
            return api.get('/api/plugins/telemetry/DEVICE/' + x.id + '/values/timeseries?keys=eto_pm,weather_sumrain,weather_tmax' +
                           '&startTs=' + estado.lunes + '&endTs=' + hasta + '&limit=5000&agg=NONE').then(function (res) {
                x.semana = {};
                ['eto_pm', 'weather_sumrain', 'weather_tmax'].forEach(function (k) {
                    var ult = {};
                    (res[k] || []).forEach(function (p) { var f = PJ.fecha(p.ts); if (!ult[f] || p.ts > ult[f].ts) ult[f] = p; });
                    Object.keys(ult).forEach(function (f) { (x.semana[f] = x.semana[f] || {})[k] = Number(ult[f].value); });
                });
            }).catch(function () {});
        })).then(function () {
            // Sector de cada estación: dentro del polígono, o el más cercano
            est.forEach(function (x) {
                var sec = G.sectores.find(function (s2) { return PJ.puntoEnPoligono(x.pos[0], x.pos[1], s2.anillos); });
                if (!sec && G.sectores.length) sec = G.sectores.slice().sort(function (a, b) { return PJ.distanciaKm(x.pos, a.centro) - PJ.distanciaKm(x.pos, b.centro); })[0];
                x.sector = sec ? sec.num : null;
            });
            var cambiado = false;
            Object.keys(estado.meteoSector).forEach(function (k) {
                var sec = k === 'def' ? null : Number(k);
                var ests = est.filter(function (x) { return x.semana && (sec === null || x.sector === sec); });
                if (!ests.length) return;
