    /* ------------------------- rutas del agua (canal) ------------------------- */
    function construirRutas() {
        var puntos = [CABECERA_CANAL];
        var secs = G.sectores.filter(function (x) { return x.num !== null; }).sort(function (a, b) { return a.num - b.num; });
        secs.forEach(function (x) { puntos.push(x.centro); });
        if (puntos.length < 2) {
