            var porSec = {};
            estado.grupos.forEach(function (g) { if (g.centro && g.sector !== null) (porSec[g.sector] = porSec[g.sector] || []).push(g.centro); });
            Object.keys(porSec).sort(function (a, b) { return a - b; }).forEach(function (k) { puntos.push(PJ.centroide([porSec[k]])); });
        }
