        if (G.tiles[k]) return G.tiles[k];
        var img = new Image();
        img.onload = function () { G.necesitaBase = true; };
        img.src = FONDOS[G.fondo].replace('{z}', z).replace('{x}', x).replace('{y}', y);
        G.tiles[k] = img;
        return img;
    }
    // Los anillos se pasan a coordenadas Mercator una sola vez (cache en el
    // propio array) y en cada cuadro solo se escalan y desplazan.
    function trazarAnillos(ctx, anillos) {
        if (!anillos._m) anillos._m = anillos.map(function (r) { return r.map(function (p) { return aMundo(p[0], p[1]); }); });
        var k = escala(), cc = aMundo(G.vista.lat, G.vista.lng), w2 = cAnim.width / DPR / 2, h2 = cAnim.height / DPR / 2;
        ctx.beginPath();
        anillos._m.forEach(function (r) {
            for (var i = 0; i < r.length; i++) {
