        xBase.fillStyle = '#F4F1EC'; xBase.fillRect(0, 0, w, h);
        if (G.fondo !== 'ninguno') {
            var zi = Math.max(0, Math.min(18, Math.floor(G.vista.z))), f = Math.pow(2, G.vista.z - zi), tam = 256 * f;
