    /* ---------------------------------- alertas ---------------------------------- */
    function calcularAlertas() {
        var hoyI = iHoy(), lista = [], porGrupo = {};
        // Reservas fuera de umbral: en cualquier semana (también la siguiente,
        // que es la que se pide los jueves), desde hoy en adelante
        var fechasSem = PJ.fechasSemana(estado.lunes), hoyF = PJ.fecha(Date.now());
        estado.grupos.forEach(function (g) {
            (g.dias || []).forEach(function (d, i) {
                if (!d.R || fechasSem[i] < hoyF) return;
                var dv = PJ.desviacionReserva(d, api.umbralReserva());
                if (dv && dv.fuera) {
                    lista.push(dv.lluvia ? { nivel: 2, id: g.id, dia: i, icono: '🌧️', titulo: 'Pide agua con lluvia prevista',
                                 texto: PJ.DIAS_LARGO[i] + ': pide ' + n1(d.pedido) + ' L/s y, por la lluvia prevista, el histórico no prevé riego' } :
                               { nivel: 2, id: g.id, dia: i, icono: dv.tipo === 'mas' ? '⬆️' : '⬇️',
                                 titulo: 'Reserva ' + (dv.tipo === 'mas' ? 'por encima' : 'por debajo') + ' de lo habitual',
                                 texto: PJ.DIAS_LARGO[i] + ': pide ' + n1(d.pedido) + ' L/s frente a ' + n1(d.qHist) + ' L/s del histórico (' + PJ.textoDesviacion(dv) + ', umbral ±' + n0(api.umbralReserva()) + ' %)' });
                }
            });
        });
        if (hoyI === -1) { lista.sort(function (a, b) { return b.nivel - a.nivel; }); G.alertas = lista; G.alertasPorGrupo = {}; return; }
        var aprob = estado.aprobado && estado.aprobado.asignaciones;
        estado.grupos.forEach(function (g) {
            var asign = aprob ? (aprob[g.id] || [0, 0, 0, 0, 0, 0, 0])
                              : estado.reparto.map(function (r) { return r.asignado[g.id] !== undefined ? r.asignado[g.id] : 0; });
            var real = g.real.slice();
            var vivo = G.vivo[g.id];
            if (vivo && (vivo.media !== null || vivo.instantaneo !== null)) real[hoyI] = vivo.media !== null ? vivo.media : vivo.instantaneo;
            // Sin reparto aprobado solo se compara si la proyección esperaba riego
            // (si no, cualquier riego no previsto saltaría como sobreconsumo).
            var sc = (aprob || asign[hoyI] > 0) ? PJ.sobreconsumo(real, asign, hoyI) : null;
            if (sc) {
                lista.push({ nivel: sc.nivel === 'alerta' ? 3 : 2, id: g.id, icono: '⚠️', titulo: (sc.nivel === 'alerta' ? 'Sobreconsumo continuado' : 'Sobreconsumo'),
                             texto: n1(sc.real) + ' L/s frente a ' + n1(sc.asignado) + ' asignados (+' + n1(sc.exceso) + ')' + (aprob ? '' : ' · sin reparto aprobado: se compara con lo previsto') });
                porGrupo[g.id] = true;
            }
            (g.lisimetros || []).forEach(function (x) {
                if (x.drenajeAlto) lista.push({ nivel: 1, id: g.id, icono: '⬇️', titulo: 'Drenaje alto (lisímetro)', texto: esc(x.nombre) + ': ' + n1(x.v.drenaje_lm2.v) + ' L/m², posible percolación' });
            });
            var est = estado.reparto[hoyI] && estado.reparto[hoyI].estado[g.id];
            if (est === 'aplazado') lista.push({ nivel: 2, id: g.id, icono: '⏸️', titulo: 'Sin agua hoy', texto: 'Pide ' + n1(g.dias[hoyI].q) + ' L/s y no hay caudal disponible' });
        });
        G.sensores.forEach(function (x) {
            var ult = 0; Object.keys(x.v).forEach(function (k) { ult = Math.max(ult, x.v[k].ts || 0); });
            if (ult && Date.now() - ult > 36 * 3600000) lista.push({ nivel: 0, sensor: x.id, icono: '📡', titulo: 'Sensor sin datos', texto: esc(x.nombre) + ' · último dato ' + new Date(ult).toLocaleDateString('es-ES') });
        });
        lista.sort(function (a, b) { return b.nivel - a.nivel; });
        G.alertas = lista; G.alertasPorGrupo = porGrupo;
    }
    function pintarAlertas() {
        var lista = G.alertas || [];
        var $a = $g.find('.gm-alertas');
        $a.html('<div class="gm-sec-t">Alertas <span>' + (lista.length ? lista.length : 'ninguna') + '</span></div>' +
            (lista.length ? lista.slice(0, 40).map(function (al, i) {
                var g = al.id ? grupoPorId(al.id) : null;
                return '<button type="button" class="gm-alerta n' + al.nivel + '" data-i="' + i + '"><span>' + al.icono + '</span><div><b>' + esc(al.titulo) + (g ? ' · ' + esc(nombre(g)) : '') + '</b><small>' + al.texto + '</small></div></button>';
            }).join('') : '<div class="gm-vacio-alertas">Todo en orden: ninguna toma supera su asignación y las reservas están dentro del umbral.</div>'));
        $a.find('.gm-alerta').on('click', function () {
            var al = lista[Number($(this).attr('data-i'))];
            var obj = al.id ? grupoPorId(al.id) : G.sensores.find(function (x) { return x.id === al.sensor; });
            var p = al.id ? obj.centro : obj.pos;
