                    (dv ? ' <b class="' + (dv.fuera ? 'rojo' : '') + '">(' + PJ.textoDesviacion(dv) + (dv.fuera && !dv.lluvia ? ', fuera de umbral' : '') + ')</b>' : '') + '</div>';
            } else if (dSel && dSel.q > 0) {
