            }
            html = '<button type="button" class="gm-ficha-x">×</button>' +
                '<div class="gm-ficha-t">' + esc(nombre(g)) + '</div>' +
                '<div class="gm-ficha-s">Sector ' + (g.sector === null ? '–' : g.sector) + ' · ' + (g.superficie ? n1(g.superficie) + ' ha' : 'sin superficie') +
                    ' · base ' + (g.base !== null ? n1(g.base) + ' L/s' : 's/h') + (g.sinGeometria ? ' · <i>sin polígono</i>' : '') + '</div>' +
                (PJ.esAtipico(g.base, g.superficie) ? '<div class="gm-ficha-l"><b class="rojo">⚠ Caudal base atípico</b> (' + (g.superficie ? n1(g.base / g.superficie) + ' L/s por ha' : 'más de 2000 L/s') + '): revisar el caudalímetro o la superficie</div>' : '') +
                '<div class="gm-ficha-e c-' + e.clase + '">' + ({ regando: 'Regando', parcial: 'Caudal reducido', aplazado: 'Sin agua (aplazada)', parada: 'Parada', inactivo: 'Sin riego' }[e.clase]) +
                    (e.q ? ' · ' + n1(e.q) + ' L/s' : '') + (e.pedido && e.clase !== 'regando' ? ' de ' + n1(e.pedido) + ' pedidos' : '') + (e.real ? ' · real' : '') + '</div>' +
