    /* ------------------------------------ arranque ------------------------------------ */
    G.iniciar = function () {
        if (G.iniciado) { G.recalcular(); calcularAlertas(); pintarLateral(); return Promise.resolve(); }
        G.iniciado = true;
        redimensionar();
        engancharMapa();
        $g.find('.gm-cargando').show();
        return cargarCapas().then(function () {
            // Las estaciones pueden haber cambiado la meteo de días pasados: recalcular
            api.recalcularTodo();
            encuadrar();
            G.dia = Math.max(0, iHoy());
            G.recalcular();
            calcularAlertas();
            G.listo = true;
            pintarEscenarios(); pintarLateral(); actualizarPlay();
            $g.find('.gm-cargando').hide();
            $g.find('.gm-fuentes').html(
                G.sectores.length + ' sectores · ' + estado.grupos.filter(function (g) { return g.anillos && g.anillos.length; }).length + '/' + estado.grupos.length + ' tomas con geometría · ' +
                G.sensores.filter(function (x) { return x.tipo === 'meteo'; }).length + ' estaciones · ' +
                G.sensores.filter(function (x) { return x.tipo === 'lisimetro'; }).length + ' lisímetros');
            if (!G.anim) G.anim = requestAnimationFrame(cuadro);
            // En vivo: refresca el caudal actual de todas las tomas cada minuto
            G.timerVivo = setInterval(function () {
                if (estado.destruido) return;
                consulta({ type: 'assetType', assetTypes: [api.perfilNombre], assetNameFilter: '' }, [],
                    [{ type: 'TIME_SERIES', key: 'media_proyectada' }, { type: 'TIME_SERIES', key: 'caudal_Sum' }]).then(function (r) {
                    var porId = {}; r.forEach(function (e) { porId[e.entityId.id] = e; });
                    estado.grupos.forEach(function (g) { if (porId[g.id]) actualizarVivo(g, porId[g.id]); });
                    calcularAlertas(); actualizarColores(); pintarLateral(); pintarFicha();
                    $g.find('.gm-vivo').addClass('latido'); setTimeout(function () { $g.find('.gm-vivo').removeClass('latido'); }, 900);
                }).catch(function () {});
            }, 60000);
        }).catch(function (e) {
            $g.find('.gm-cargando').html('No se pudieron cargar las capas del mapa.').show();
            console.error('[Gemelo]', e);
        });
    };
    G.nuevaSemana = function () {
        // Las capas (geometría, sensores) no cambian: solo la meteo medida de
        // la nueva semana, la proyección y las alertas.
        if (!G.iniciado) return Promise.resolve();
        G.listo = false;
        return meteoEstaciones().then(function () {
            api.recalcularTodo();
            G.dia = iHoy() === -1 ? 0 : iHoy();
            G.modo = 'previsto';
            G.recalcular(); calcularAlertas();
            G.listo = true; G.necesitaBase = true;
            pintarLateral(); pintarFicha();
        });
    };
    G.refrescarAlertas = function () { if (G.listo) { calcularAlertas(); pintarLateral(); pintarFicha(); } };
    G.destruir = function () {
        clearInterval(G.timerVivo);
        if (G.anim) cancelAnimationFrame(G.anim);
        $(window).off('.gemelo');
        if (G.ro) G.ro.disconnect();
    };

    $g.find('.gm-play').on('click', function () {
        G.play = !G.play;
        if (G.play) G.progreso = 0;
        actualizarPlay();
    });
    $g.find('.gm-vel').on('click', function () { G.velocidad = Number($(this).attr('data-vel')); actualizarPlay(); });
    return G;
}


/* =========================== WIDGET (ThingsBoard) ========================= */

self.onInit = function () {
    var $ctx = self.ctx;
    var $c = $ctx.$container;
    var s = $ctx.settings || {};

    var PROFILE_NAME = s.profileName || 'Grupo_Riego';
    var RESUMEN_NAME = s.resumenAssetName || 'CRBG_Resumen_Caudales';
    // Coordenadas aproximadas de cada sector a lo largo del Canal del Bajo
    // Guadalquivir (de Peñaflor a las marismas). AJUSTAR en los ajustes del
    // widget (coordenadasSector) con el punto representativo de cada sector.
    var COORD_SECTOR = s.coordenadasSector || {
        0: [37.66, -5.53],  // Lora del Río
        1: [37.55, -5.66],  // Alcolea / Carmona norte
        2: [37.45, -5.76],  // Carmona
        3: [37.30, -5.92],  // Alcalá de Guadaíra / Dos Hermanas
        4: [37.16, -5.93],  // Los Palacios (Maribáñez)
        5: [37.00, -6.03]   // Las Cabezas / Lebrija
    };
    var COORD_DEFECTO = s.coordenadasDefecto || [37.30, -5.92];
    var LOTE = 8; // peticiones simultáneas a ThingsBoard
    // El agua se pide los jueves para la semana siguiente: de jueves a domingo
    // el panel se abre directamente en la semana que se está pidiendo.
    var SEMANA_SIGUIENTE_DESDE_JUEVES = s.semanaSiguienteDesdeJueves !== false;
    function semanaPorDefecto() {
        var hoy = Date.now(), dow = (new Date(hoy).getDay() + 6) % 7; // 0 = lunes, 3 = jueves
        var l = PJ.lunesDe(hoy);
        return (SEMANA_SIGUIENTE_DESDE_JUEVES && dow >= 3) ? PJ.sumarDias(l, 7) : l;
    }

    var estado = {
        lunes: semanaPorDefecto(),
        perfilId: null, resumenId: null,
        umbralReserva: (s.umbralAvisoReserva !== undefined && s.umbralAvisoReserva !== '' && !isNaN(s.umbralAvisoReserva)) ? Number(s.umbralAvisoReserva) : PJ.UMBRAL_RESERVA_PCT,
        grupos: [], meteoSector: {}, disponible: [null, null, null, null, null, null, null],
        reparto: null, fijada: null, aprobado: null,
        filtroSector: '', filtroTexto: '', soloCambios: false, vista: 'gemelo',
        cargando: false, destruido: false
    };
    self._pjEstado = estado;

    /* ---------- utilidades de interfaz ---------- */
    function esc(v) {
        return String(v == null ? '' : v).replace(/[&<>"']/g, function (ch) {
            return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch];
        });
    }
    function n0(v) { return (v === null || v === undefined || isNaN(v)) ? '–' : Math.round(v).toLocaleString('es-ES'); }
    function n1(v) { return (v === null || v === undefined || isNaN(v)) ? '–' : (Math.round(v * 10) / 10).toLocaleString('es-ES', { maximumFractionDigits: 1 }); }
    function fechaCorta(ts) { return new Date(ts).toLocaleDateString('es-ES', { day: 'numeric', month: 'short' }); }
    function progreso(texto, pct) {
        $c.find('.pj-progreso').show().find('.pj-progreso-texto').text(texto);
        $c.find('.pj-progreso-barra i').css('width', Math.max(3, Math.min(100, pct || 0)) + '%');
    }
    function finProgreso() { $c.find('.pj-progreso').hide(); }
    function aviso(texto, tipo) {
        var $a = $c.find('.pj-aviso');
        $a.removeClass('pj-aviso-ok pj-aviso-error').addClass(tipo === 'error' ? 'pj-aviso-error' : 'pj-aviso-ok').text(texto).show();
        clearTimeout(estado._avisoT);
        estado._avisoT = setTimeout(function () { $a.fadeOut(300); }, 4000);
    }
    function usuarioActual() {
        var u = $ctx.currentUser || {};
        if (u.sub || u.email) return u.sub || u.email;
        try {
            var jwt = localStorage.getItem('jwt_token');
            if (jwt) {
                var d = JSON.parse(decodeURIComponent(escape(atob(jwt.split('.')[1].replace(/-/g, '+').replace(/_/g, '/')))));
                return d.sub || d.email || '';
            }
        } catch (e) {}
        return '';
    }

    /* ---------- acceso a ThingsBoard ---------- */
    function get(url) {
        return new Promise(function (ok, ko) { $ctx.http.get(url).subscribe(ok, ko); });
    }
    function post(url, body) {
        return new Promise(function (ok, ko) { $ctx.http.post(url, body).subscribe(ok, ko); });
    }
    function getReintento(url, intentos) {
        return get(url).catch(function (e) {
            if ((intentos || 0) > 0) return getReintento(url, intentos - 1);
            throw e;
        });
    }
    function enLotes(items, fn, onProgreso) {
        var i = 0, hechos = 0;
        return new Promise(function (ok) {
            if (!items.length) { ok(); return; }
            var activos = 0;
            function lanzar() {
                while (activos < LOTE && i < items.length) {
                    (function (item) {
                        activos++;
                        Promise.resolve(fn(item)).catch(function () {}).then(function () {
                            activos--; hechos++;
                            if (onProgreso) onProgreso(hechos, items.length);
                            if (hechos === items.length) ok(); else lanzar();
                        });
                    })(items[i++]);
                }
            }
            lanzar();
        });
    }
    function resolverEntidades() {
        return get('/api/assetProfiles?pageSize=100&page=0&sortProperty=name&sortOrder=ASC').then(function (r) {
            var p = r && r.data && r.data.find(function (x) { return x.name === PROFILE_NAME; });
            estado.perfilId = p ? p.id.id : null;
        }).catch(function () {}).then(function () {
            return get('/api/tenant/assets?assetName=' + encodeURIComponent(RESUMEN_NAME)).then(function (a) {
                estado.resumenId = a && a.id ? a.id.id : null;
            }).catch(function () { estado.resumenId = null; });
        });
    }
    function cargarGrupos() {
        var todos = [];
        function pagina(n) {
            return get('/api/user/assets?pageSize=1000&page=' + n + '&sortProperty=name&sortOrder=ASC').then(function (r) {
                todos = todos.concat((r && r.data) || []);
                if (r && r.hasNext) return pagina(n + 1);
            });
        }
        return pagina(0).then(function () {
            return todos.filter(function (a) { return a.assetProfileId && a.assetProfileId.id === estado.perfilId; })
                .map(function (a) { return { id: a.id.id, nombre: a.name, etiqueta: a.label || a.name, visible: PJ.nombreConRemota(a.name) }; });
        });
    }
    function norm(t) {
        return String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]/g, '');
    }

    /* ---------- datos por grupo ---------- */
    function cargarDatosGrupo(g) {
        var lunes = estado.lunes;
        var desde = PJ.sumarDias(lunes, -35);
        var hasta = PJ.sumarDias(lunes, 7) - 1;
        var uAttr = '/api/plugins/telemetry/ASSET/' + g.id + '/values/attributes/SERVER_SCOPE';
        var uTs = '/api/plugins/telemetry/ASSET/' + g.id + '/values/timeseries?keys=caudal_fijado,caudal_manual,reserva,parada,peticion' +
                  '&startTs=' + desde + '&endTs=' + hasta + '&limit=20000&agg=NONE';
        return Promise.all([getReintento(uAttr, 1).catch(function () { return []; }), getReintento(uTs, 1)]).then(function (res) {
            var attrs = res[0] || [], ts = res[1] || {};
            g.sector = null; g.superficie = null;
            var haPlano = null;
            attrs.forEach(function (a) {
                var k = norm(a.key);
                if (k === 'sector') { var v = parseFloat(String(a.value).replace(/\D/g, '')); g.sector = isNaN(v) ? null : v; }
                if (k === 'superficiehaestimada') { var h = parseFloat(a.value); if (!isNaN(h) && h > 0) g.superficie = h; }
                if (k === 'ha') { var h2 = parseFloat(a.value); if (!isNaN(h2) && h2 > 0) haPlano = h2; }
            });
            if (!g.superficie && haPlano) g.superficie = haPlano;
            g.porDia = PJ.caudalPorDia(ts.caudal_fijado, ts.caudal_manual);
            g.marcas = {};
            function marca(f) { return g.marcas[f] || (g.marcas[f] = {}); }
            (ts.reserva || []).forEach(function (p) { if (p.value) marca(PJ.fecha(p.ts)).R = true; });
            (ts.parada || []).forEach(function (p) { if (p.value) marca(PJ.fecha(p.ts)).P = true; });
            (ts.peticion || []).forEach(function (p) {
                var v = p.value;
                try { v = typeof v === 'string' ? JSON.parse(v) : v; } catch (e) { v = null; }
                if (v) marca(PJ.fecha(p.ts)).pet = { caudal: v.caudal, pedidoEn: v.pedidoEn, usuario: v.usuario };
            });
            Object.keys(g.marcas).forEach(function (f) { if (g.marcas[f].P) g.marcas[f].R = false; });

            var fechasRec = [];
            for (var i = 28; i >= 1; i--) fechasRec.push(PJ.fecha(PJ.sumarDias(lunes, -i) + 12 * 3600000));
            var b = PJ.caudalBase(g.porDia, fechasRec, null, null);
            if (b.diasRiego >= PJ.MIN_DIAS_HISTORICO) { g.baseInfo = b; return; }
            // Pocos datos recientes: misma época de la campaña anterior (±10 días)
            var lunesAnt = PJ.lunesDe(PJ.sumarDias(lunes, -364));
            var dA = PJ.sumarDias(lunesAnt, -10), hA = PJ.sumarDias(lunesAnt, 17) - 1;
            var fechasAnt = [];
            for (var j = -10; j < 17; j++) fechasAnt.push(PJ.fecha(PJ.sumarDias(lunesAnt, j) + 12 * 3600000));
            return getReintento('/api/plugins/telemetry/ASSET/' + g.id + '/values/timeseries?keys=caudal_fijado,caudal_manual' +
                                '&startTs=' + dA + '&endTs=' + hA + '&limit=20000&agg=NONE', 1).then(function (tsA) {
                g.baseInfo = PJ.caudalBase(g.porDia, fechasRec, PJ.caudalPorDia(tsA.caudal_fijado, tsA.caudal_manual), fechasAnt);
            }).catch(function () { g.baseInfo = b; });
        }).catch(function () {
            g.error = true; g.porDia = {}; g.marcas = {}; g.baseInfo = { base: null, fuente: 'error de lectura', diasRiego: 0 };
        });
    }

    /* ---------- meteorología (Open-Meteo, fuera de ThingsBoard) ---------- */
    // Se usa fetch() y no $ctx.http para no enviar el token de ThingsBoard a
    // un servicio externo.
    function cargarMeteo(sectores) {
        var fechas = PJ.fechasSemana(estado.lunes);
        var cacheKey = 'pj-meteo-' + fechas[0];
        var cache = null;
        try { cache = JSON.parse(localStorage.getItem(cacheKey) || 'null'); } catch (e) {}
        if (cache && cache.t > Date.now() - 3 * 3600000) { estado.meteoSector = cache.d; return Promise.resolve(); }
        var resultado = {};
        return Promise.all(sectores.map(function (sec) {
            var co = COORD_SECTOR[sec] || COORD_DEFECTO;
            var q = '?latitude=' + co[0] + '&longitude=' + co[1] + '&timezone=Europe%2FMadrid' +
                    '&daily=et0_fao_evapotranspiration,precipitation_sum,temperature_2m_max';
            var prev = fetch('https://api.open-meteo.com/v1/forecast' + q + '&start_date=' + fechas[0] + '&end_date=' + fechas[6])
                .then(function (r) { return r.ok ? r.json() : null; }).catch(function () { return null; });
            // ET0 normal: misma semana de los 3 años anteriores
            var normales = [1, 2, 3].map(function (a) {
                var ini = new Date(PJ.sumarDias(estado.lunes, -364 * a) + 12 * 3600000);
                var fin = new Date(PJ.sumarDias(estado.lunes, -364 * a + 6) + 12 * 3600000);
                return fetch('https://archive-api.open-meteo.com/v1/archive' + q.replace(',precipitation_sum,temperature_2m_max', '') +
                             '&start_date=' + PJ.fecha(ini.getTime()) + '&end_date=' + PJ.fecha(fin.getTime()))
                    .then(function (r) { return r.ok ? r.json() : null; }).catch(function () { return null; });
            });
            return Promise.all([prev].concat(normales)).then(function (rs) {
                var p = rs[0] && rs[0].daily;
                var dias = [];
                for (var i = 0; i < 7; i++) {
                    var vals = [];
                    rs.slice(1).forEach(function (r) {
                        var v = r && r.daily && r.daily.et0_fao_evapotranspiration && r.daily.et0_fao_evapotranspiration[i];
                        if (v !== null && v !== undefined) vals.push(v);
                    });
                    dias.push({
                        et0: p && p.et0_fao_evapotranspiration ? p.et0_fao_evapotranspiration[i] : null,
                        lluvia: p && p.precipitation_sum ? p.precipitation_sum[i] : null,
                        tmax: p && p.temperature_2m_max ? p.temperature_2m_max[i] : null,
                        et0Normal: vals.length ? PJ.media(vals) : null
                    });
                }
                resultado[sec] = { dias: dias, ok: !!p };
            });
        })).then(function () {
            estado.meteoSector = resultado;
            var algunoOk = Object.keys(resultado).some(function (k) { return resultado[k].ok; });
            if (algunoOk) { try { localStorage.setItem(cacheKey, JSON.stringify({ t: Date.now(), d: resultado })); } catch (e) {} }
        });
    }
    function meteoDe(g) {
        var m = estado.meteoSector[g.sector] || estado.meteoSector['def'];
        return (m && m.dias) || [{}, {}, {}, {}, {}, {}, {}];
    }

    /* ---------- configuración guardada en el activo de resumen ---------- */
    function claveSemana() { return PJ.fecha(estado.lunes + 12 * 3600000); }
    function cargarConfigSemana() {
        if (!estado.resumenId) return Promise.resolve();
        var k1 = 'caudal_disponible_' + claveSemana(), k2 = 'reparto_aprobado_' + claveSemana(), k3 = 'umbral_aviso_reserva';
        return Promise.all([
            get('/api/plugins/telemetry/ASSET/' + estado.resumenId + '/values/attributes/SERVER_SCOPE?keys=' + k1 + ',' + k2 + ',' + k3).catch(function () { return []; }),
            get('/api/plugins/telemetry/ASSET/' + estado.resumenId + '/values/timeseries?keys=proyeccion_semana&startTs=' + estado.lunes +
                '&endTs=' + (estado.lunes + 1000) + '&limit=1&agg=NONE').catch(function () { return {}; })
        ]).then(function (r) {
            estado.disponible = [null, null, null, null, null, null, null];
            estado.aprobado = null; estado.fijada = null;
            (r[0] || []).forEach(function (a) {
                var v = a.value;
                try { v = typeof v === 'string' ? JSON.parse(v) : v; } catch (e) { v = null; }
                if (a.key === k1 && Array.isArray(v)) estado.disponible = v.map(function (x) { return (x === null || x === '' || isNaN(x)) ? null : Number(x); });
                if (a.key === k2 && v) estado.aprobado = v;
                if (a.key === k3 && v !== null && v !== '' && !isNaN(v)) estado.umbralReserva = Number(v);
            });
            var pts = (r[1] && r[1].proyeccion_semana) || [];
            if (pts.length) {
                try { estado.fijada = typeof pts[0].value === 'string' ? JSON.parse(pts[0].value) : pts[0].value; } catch (e) { estado.fijada = null; }
            }
        });
    }
    function guardarAtributoResumen(clave, valor) {
        if (!estado.resumenId) return Promise.reject(new Error('Sin activo ' + RESUMEN_NAME));
        var body = {}; body[clave] = JSON.stringify(valor);
        return post('/api/plugins/telemetry/ASSET/' + estado.resumenId + '/SERVER_SCOPE', body);
    }
    function fijarProyeccion(automatico) {
        if (!estado.resumenId) return Promise.resolve();
        var g = {};
        estado.grupos.forEach(function (x) { g[x.id] = x.dias.map(function (d) { return d.q; }); });
        var snap = { v: 1, calculadoEn: Date.now(), usuario: usuarioActual(), auto: !!automatico, g: g };
        return post('/api/plugins/telemetry/ASSET/' + estado.resumenId + '/timeseries/ANY',
                    { ts: estado.lunes, values: { proyeccion_semana: JSON.stringify(snap) } }).then(function () {
            estado.fijada = snap;
        });
    }

    /* ---------- cálculo completo ---------- */
    function calcular() {
        var fechas = PJ.fechasSemana(estado.lunes);
        var fechasPrevias = [PJ.fecha(PJ.sumarDias(estado.lunes, -2) + 12 * 3600000), PJ.fecha(PJ.sumarDias(estado.lunes, -1) + 12 * 3600000)];
        estado.grupos.forEach(function (g) {
            g.base = g.baseInfo ? g.baseInfo.base : null;
            g.activoInicio = PJ.activoAlInicio(g.porDia || {}, fechasPrevias, g.marcas);
            g.real = fechas.map(function (f) { return (g.porDia && g.porDia[f] !== undefined) ? g.porDia[f] : null; });
        });
        var res = PJ.calcularSemana(estado.grupos, fechas, meteoDe, estado.disponible, null);
        estado.grupos.forEach(function (g) { g.dias = res.dias[g.id]; });
        estado.reparto = res.reparto;
        if (estado.gemelo) estado.gemelo.recalcular();
    }

    /* ---------- carga de la semana ---------- */
    function cargarSemana() {
        if (estado.cargando) return;
        estado.cargando = true;
        pintarCabecera();
        progreso('Buscando grupos de riego…', 2);
        var p = (estado.perfilId === null) ? resolverEntidades() : Promise.resolve();
        p.then(function () {
            if (!estado.perfilId) throw new Error('No se encontró el perfil de activo "' + PROFILE_NAME + '".');
            return cargarGrupos();
        }).then(function (grupos) {
            estado.grupos = grupos;
            progreso('Leyendo histórico, reservas y paradas de ' + grupos.length + ' grupos…', 5);
            return enLotes(grupos, cargarDatosGrupo, function (h, t) {
                progreso('Leyendo histórico, reservas y paradas… ' + h + '/' + t, 5 + 80 * h / t);
            });
        }).then(function () {
            progreso('Consultando la previsión meteorológica…', 88);
            var sectores = {};
            estado.grupos.forEach(function (g) { sectores[g.sector === null ? 'def' : g.sector] = true; });
            return cargarMeteo(Object.keys(sectores));
        }).then(function () {
            progreso('Leyendo caudal disponible y reparto…', 95);
            return cargarConfigSemana();
        }).then(function () {
            calcular();
            // "Se establece cada lunes": la primera vez que se calcula la semana
            // en curso, la proyección queda fijada (con la fecha del lunes).
            var esSemanaActual = PJ.lunesDe(Date.now()) === estado.lunes;
            if (esSemanaActual && !estado.fijada) {
                return fijarProyeccion(true).catch(function () {
                    console.warn('[Proyección] No se pudo fijar la proyección de la semana.');
                });
            }
        }).then(function () {
            estado.cargando = false;
            finProgreso();
            pintarTodo();
            if (estado.vista === 'gemelo') arrancarGemelo();
        }).catch(function (err) {
            estado.cargando = false;
            finProgreso();
            var msg = esc(err && err.message ? err.message : 'Error de comunicación con el servidor.');
            $c.find('.pj-cuerpo').html('<div class="pj-vacio"><strong>No se pudo calcular la proyección</strong>' + msg + '</div>');
            $c.find('.gm-cargando').html('<strong>No se pudo calcular la proyección</strong><br>' + msg).show();
        });
    }

    /* ============================ PINTADO ============================ */
    function pintarCabecera() {
        var fin = PJ.sumarDias(estado.lunes, 6);
        $c.find('.pj-semana').text('Semana del ' + fechaCorta(estado.lunes) + ' al ' + fechaCorta(fin) + ' ' + new Date(fin).getFullYear());
        var esActual = PJ.lunesDe(Date.now()) === estado.lunes;
        $c.find('.pj-btn-hoy').prop('disabled', esActual);
        $c.find('.pj-btn-pedir').prop('disabled', PJ.sumarDias(PJ.lunesDe(Date.now()), 7) === estado.lunes);
    }

    function totalesDia(i) {
        var dem = 0, real = 0, hayReal = false, hist = 0, res = 0;
        estado.grupos.forEach(function (g) {
            var d = g.dias[i];
            dem += d.q;
            if (d.qHist !== null) hist += d.qHist;
            if (d.pedido !== null) res += d.pedido;
            if (g.real[i] !== null) { real += g.real[i]; hayReal = true; }
        });
        return { demanda: dem, real: hayReal ? real : null, historico: hist, reservado: res };
    }
    // Reservas de la semana con su desviación frente al histórico
    function resumenReservas() {
        var lista = [];
        estado.grupos.forEach(function (g) {
            g.dias.forEach(function (d, i) {
                if (!d.R) return;
                lista.push({ g: g, i: i, d: d, dv: PJ.desviacionReserva(d, estado.umbralReserva) });
            });
        });
        lista.sort(function (a, b) {
            var fa = a.dv && a.dv.fuera ? 0 : (a.d.sinCaudal ? 1 : 2), fb = b.dv && b.dv.fuera ? 0 : (b.d.sinCaudal ? 1 : 2);
            if (fa !== fb) return fa - fb;
            if (a.i !== b.i) return a.i - b.i;
            return a.g.nombre.localeCompare(b.g.nombre, 'es');
        });
        return { lista: lista, fuera: lista.filter(function (x) { return x.dv && x.dv.fuera; }).length,
                 sinCaudal: lista.filter(function (x) { return x.d.sinCaudal; }).length };
    }

    function pintarTodo() {
        pintarCabecera();
        if (!estado.grupos.length) {
            $c.find('.pj-cuerpo').html('<div class="pj-vacio"><strong>Sin grupos de riego</strong>No hay activos con el perfil "' + esc(PROFILE_NAME) + '".</div>');
            return;
        }
        $c.find('.pj-cuerpo').html(
            '<div class="pj-kpis"></div>' +
            '<div class="pj-estado-fijada"></div>' +
            '<section class="pj-panel"><div class="pj-panel-titulo">Semana día a día <span>Meteorología, demanda prevista y reparto del caudal disponible</span></div><div class="pj-dias-wrap"><table class="pj-dias"></table></div></section>' +
            '<section class="pj-panel"><div class="pj-panel-titulo">Reservas de la semana <span>Caudal pedido en el calendario frente al previsto por histórico</span></div><div class="pj-reservas"></div></section>' +
            '<section class="pj-panel pj-panel-propuestas"><div class="pj-panel-titulo">Propuestas de reparto <span>El técnico decide: nada se aplica en campo automáticamente</span></div><div class="pj-propuestas"></div></section>' +
            '<section class="pj-panel"><div class="pj-panel-titulo">Proyección por grupo de riego <span class="pj-leyenda-grupos"></span></div>' +
                '<div class="pj-filtros"></div><div class="pj-grupos-wrap"><table class="pj-grupos"></table></div></section>'
        );
        pintarKpis(); pintarEstadoFijada(); pintarDias(); pintarReservas(); pintarPropuestas(); pintarFiltros(); pintarGrupos();
    }

    function pintarReservas() {
        var rs = resumenReservas();
        var hoyF = PJ.fecha(Date.now()), fechas = PJ.fechasSemana(estado.lunes);
        var cab = '<div class="pj-umbral">Avisar si la reserva se desvía del histórico más de ' +
            '<input type="number" min="0" max="500" step="5" class="pj-input-umbral" value="' + estado.umbralReserva + '"> %' +
            '<span class="pj-prop-nota">Se guarda para todas las semanas. ' + rs.lista.length + ' reserva' + (rs.lista.length === 1 ? '' : 's') +
            (rs.fuera ? ' · <b class="pj-deficit-txt">' + rs.fuera + ' fuera de umbral</b>' : '') + (rs.sinCaudal ? ' · ' + rs.sinCaudal + ' sin caudal' : '') + '</span></div>';
        var cuerpo;
        if (!rs.lista.length) {
            cuerpo = '<div class="pj-prop-vacio" style="padding:10px 14px">No hay reservas (R) en el calendario para esta semana.</div>';
        } else {
            cuerpo = '<div class="pj-grupos-wrap" style="max-height:320px"><table class="pj-grupos pj-tabla-reservas"><thead><tr>' +
                '<th class="pj-col-sector">Sector</th><th class="pj-col-grupo">Grupo</th><th>Día</th><th>Reservado<small>L/s</small></th><th>Histórico<small>L/s</small></th><th>Desviación</th><th>Pedido el</th></tr></thead><tbody>' +
                rs.lista.map(function (x) {
                    var d = x.d, dv = x.dv, pasado = fechas[x.i] < hoyF;
                    var desv = d.sinCaudal ? '<span class="pj-gris">sin caudal: se usa el histórico</span>' :
                        (dv ? '<span class="pj-tag ' + (dv.fuera ? 'pj-tag-aplazado' : 'pj-tag-adelanto') + '">' + (dv.lluvia ? '🌧️ pide agua con lluvia prevista' : PJ.textoDesviacion(dv) + (dv.fuera ? (dv.tipo === 'mas' ? ' · coge más' : ' · coge menos') : '')) + '</span>' : '<span class="pj-gris">sin histórico</span>');
                    return '<tr' + (pasado ? ' class="pj-gris"' : '') + '><td class="pj-col-sector">' + (x.g.sector === null ? '–' : x.g.sector) + '</td>' +
                        '<td class="pj-col-grupo">' + esc(x.g.visible) + '</td><td>' + PJ.DIAS[x.i] + ' ' + new Date(PJ.sumarDias(estado.lunes, x.i)).getDate() + '</td>' +
                        '<td><b>' + (d.pedido !== null ? n1(d.pedido) : '–') + '</b></td><td>' + (d.qHist !== null ? n1(d.qHist) : '–') + '</td><td>' + desv + '</td>' +
                        '<td class="pj-gris">' + (d.pedidoEn ? new Date(d.pedidoEn).toLocaleString('es-ES', { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) : '') + '</td></tr>';
                }).join('') + '</tbody></table></div>';
        }
        $c.find('.pj-reservas').html(cab + cuerpo);
        $c.find('.pj-input-umbral').on('change', function () {
            var v = parseFloat(String($(this).val()).replace(',', '.'));
            if (isNaN(v) || v < 0) { $(this).val(estado.umbralReserva); return; }
            estado.umbralReserva = v;
            guardarAtributoResumen('umbral_aviso_reserva', v).then(function () {
                aviso('Umbral de aviso de reservas guardado: ±' + n0(v) + ' %.');
            }).catch(function () { aviso('No se pudo guardar el umbral.', 'error'); });
            pintarKpis(); pintarReservas(); pintarGrupos();
            if (estado.gemelo && estado.gemelo.iniciado) estado.gemelo.refrescarAlertas();
        });
    }

    function pintarKpis() {
        var demM3 = 0, sumaDisp = 0, nDisp = 0, sumaDem = 0, lluviaMax = 0;
        var peticiones = 0, paradas = 0;
        for (var i = 0; i < 7; i++) {
            var t = totalesDia(i); sumaDem += t.demanda; demM3 += t.demanda * 86.4;
            if (estado.disponible[i] !== null) { sumaDisp += estado.disponible[i]; nDisp++; }
        }
        estado.grupos.forEach(function (g) {
            g.dias.forEach(function (d) { if (d.R) peticiones++; if (d.P) paradas++; });
        });
        Object.keys(estado.meteoSector).forEach(function (k) {
            var tot = 0; (estado.meteoSector[k].dias || []).forEach(function (d) { tot += d.lluvia || 0; });
            lluviaMax = Math.max(lluviaMax, tot);
        });
        var deficitDias = estado.reparto.filter(function (r) { return r.deficit > 0; }).length;
        var rs = resumenReservas();
        var atipicos = estado.grupos.filter(function (g) { return PJ.esAtipico(g.base, g.superficie) && g.dias.some(function (d) { return d.q > 0; }); });
        var m3Atip = 0; atipicos.forEach(function (g) { g.dias.forEach(function (d) { m3Atip += d.q * 86.4; }); });
        var kpi = function (titulo, valor, unidad, nota, clase) {
            return '<div class="pj-kpi ' + (clase || '') + '"><div class="pj-kpi-t">' + titulo + '</div><div class="pj-kpi-v">' + valor +
                   '<small>' + unidad + '</small></div><div class="pj-kpi-n">' + nota + '</div></div>';
        };
        $c.find('.pj-kpis').html(
            kpi('Demanda prevista', n0(demM3), 'm³', atipicos.length ? '⚠ ' + n0(m3Atip / demM3 * 100) + ' % viene de ' + atipicos.length + ' toma' + (atipicos.length > 1 ? 's' : '') + ' con dato atípico' : 'volumen de la semana', atipicos.length ? 'pj-kpi-aviso' : '') +
            kpi('Caudal medio', n0(sumaDem / 7), 'L/s', 'previsto lunes a domingo') +
            kpi('Disponible medio', nDisp ? n0(sumaDisp / nDisp) : '–', nDisp ? 'L/s' : '', nDisp ? nDisp + ' de 7 días introducidos' : 'introdúcelo abajo, por día') +
            kpi('Días con déficit', deficitDias, '', deficitDias ? 'la demanda supera el disponible' : 'el disponible cubre la demanda', deficitDias ? 'pj-kpi-alerta' : '') +
            kpi('Peticiones / paradas', peticiones + ' / ' + paradas, '', 'reservas (R) y paradas (P) de la semana') +
            kpi('Reservas fuera de umbral', rs.fuera, '', rs.fuera ? 'se desvían más de ±' + n0(estado.umbralReserva) + ' % del histórico' : 'todas dentro de ±' + n0(estado.umbralReserva) + ' %', rs.fuera ? 'pj-kpi-alerta' : '') +
            kpi('Lluvia prevista', n0(lluviaMax), 'mm', 'máximo acumulado entre sectores')
        );
    }

    function pintarEstadoFijada() {
        var html = '';
        if (estado.fijada) {
            var tot = 0; Object.keys(estado.fijada.g || {}).forEach(function (id) { (estado.fijada.g[id] || []).forEach(function (q) { tot += q; }); });
            html += '<span class="pj-chip">📌 Proyección fijada el ' + new Date(estado.fijada.calculadoEn).toLocaleString('es-ES', { weekday: 'long', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) +
                    ': ' + n0(tot * 86.4) + ' m³</span>';
        } else if (PJ.lunesDe(Date.now()) < estado.lunes) {
            var jueves = PJ.sumarDias(estado.lunes, -4);
            html += '<span class="pj-chip pj-chip-gris">Semana futura: el agua se pide hasta el jueves ' + fechaCorta(jueves) + '. La proyección se fijará al empezar la semana</span>';
        } else {
            html += '<span class="pj-chip pj-chip-gris">Esta semana no tiene proyección fijada</span>';
        }
        if (estado.aprobado) {
            html += '<span class="pj-chip pj-chip-ok">✔ Reparto aprobado por ' + esc(estado.aprobado.usuario || '—') + ' el ' +
                    new Date(estado.aprobado.aprobadoEn).toLocaleString('es-ES', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) + '</span>';
        }
        if (!estado.resumenId) html += '<span class="pj-chip pj-chip-error">No se encontró el activo "' + esc(RESUMEN_NAME) + '": no se puede guardar</span>';
        $c.find('.pj-estado-fijada').html(html);
    }

    function pintarDias() {
        var fechas = PJ.fechasSemana(estado.lunes);
        var hoy = PJ.fecha(Date.now());
        var cab = '<tr><th></th>' + fechas.map(function (f, i) {
            var d = PJ.sumarDias(estado.lunes, i);
            return '<th class="' + (f === hoy ? 'pj-hoy' : '') + '">' + PJ.DIAS[i] + '<small>' + new Date(d).getDate() + '</small></th>';
        }).join('') + '<th>Semana</th></tr>';

        // Meteorología: media entre sectores
        function mediaMeteo(i, campo) {
            var v = [];
            Object.keys(estado.meteoSector).forEach(function (k) { var d = (estado.meteoSector[k].dias || [])[i]; if (d && d[campo] !== null && d[campo] !== undefined) v.push(d[campo]); });
            return v.length ? PJ.media(v) : null;
        }
        var filas = '';
        filas += '<tr class="pj-fila-meteo"><td>Tiempo <small>media de sectores</small></td>' + fechas.map(function (f, i) {
            var tm = mediaMeteo(i, 'tmax'), ll = mediaMeteo(i, 'lluvia');
            var icono = (ll !== null && ll >= PJ.LLUVIA_MIN_MM) ? '🌧️' : (ll !== null && ll > 0.5 ? '🌦️' : (tm !== null && tm >= 32 ? '🔥' : '☀️'));
            return '<td title="Máxima ' + (tm !== null ? n0(tm) + '°' : '–') + ' · lluvia ' + (ll !== null ? n1(ll) + ' mm' : '–') + '">' + icono + '<div>' + (tm !== null ? n0(tm) + '°' : '–') + '</div><small>' + (ll !== null ? n1(ll) + ' mm lluvia' : '') + '</small></td>';
        }).join('') + '<td></td></tr>';
        filas += '<tr><td>Corrector de calor <small>ET0 prevista / normal</small></td>' + fechas.map(function (f, i) {
            var e = mediaMeteo(i, 'et0'), en = mediaMeteo(i, 'et0Normal');
            var k = PJ.corrector(e, en);
            var cls = k > 1.05 ? 'pj-sube' : (k < 0.95 ? 'pj-baja' : '');
            return '<td class="' + cls + '" title="ET0 prevista ' + n1(e) + ' mm · normal ' + n1(en) + ' mm">×' + (Math.round(k * 100) / 100).toLocaleString('es-ES') + '</td>';
        }).join('') + '<td></td></tr>';

        var semDem = 0, semDisp = 0, hayDisp = false, semHist = 0, semRes = 0;
        filas += '<tr><td>Previsto por histórico <small>L/s · base × calor − lluvia</small></td>' + fechas.map(function (f, i) {
            var t = totalesDia(i); semHist += t.historico * 86.4;
            return '<td>' + n0(t.historico) + '</td>';
        }).join('') + '<td>' + n0(semHist) + ' m³</td></tr>';
        filas += '<tr><td>Reservado en el calendario <small>L/s pedidos (Zona regable)</small></td>' + fechas.map(function (f, i) {
            var t = totalesDia(i); semRes += t.reservado * 86.4;
            return '<td>' + (t.reservado ? n0(t.reservado) : '<span class="pj-gris">–</span>') + '</td>';
        }).join('') + '<td>' + (semRes ? n0(semRes) + ' m³' : '–') + '</td></tr>';
        filas += '<tr class="pj-fila-fuerte"><td>Demanda prevista <small>L/s · reservado si lo hay; si no, histórico</small></td>' + fechas.map(function (f, i) {
            var t = totalesDia(i); semDem += t.demanda * 86.4;
            return '<td>' + n0(t.demanda) + '</td>';
        }).join('') + '<td>' + n0(semDem) + ' m³</td></tr>';
        filas += '<tr class="pj-fila-disp"><td>Caudal disponible <small>L/s · lo introduce el técnico</small></td>' + fechas.map(function (f, i) {
            var v = estado.disponible[i];
            if (v !== null) { semDisp += v * 86.4; hayDisp = true; }
            return '<td><input type="number" min="0" step="any" class="pj-input-disp" data-dia="' + i + '" value="' + (v === null ? '' : v) + '" placeholder="—"></td>';
        }).join('') + '<td>' + (hayDisp ? n0(semDisp) + ' m³' : '–') + '</td></tr>';
        filas += '<tr><td>Balance <small>disponible − demanda</small></td>' + estado.reparto.map(function (r, i) {
            if (estado.disponible[i] === null) return '<td class="pj-gris">–</td>';
            var bal = estado.disponible[i] - r.demanda;
            return '<td class="' + (bal < 0 ? 'pj-deficit' : 'pj-excedente') + '">' + (bal > 0 ? '+' : '') + n0(bal) + '</td>';
        }).join('') + '<td></td></tr>';
        filas += '<tr class="pj-fila-real"><td>Real <small>días ya pasados, L/s</small></td>' + fechas.map(function (f, i) {
            var t = totalesDia(i);
            return '<td>' + (f < hoy && t.real !== null ? n0(t.real) : '') + '</td>';
        }).join('') + '<td></td></tr>';
        $c.find('.pj-dias').html('<thead>' + cab + '</thead><tbody>' + filas + '</tbody>');

        $c.find('.pj-input-disp').on('change', function () {
            var i = Number($(this).attr('data-dia'));
            var v = parseFloat(String($(this).val()).replace(',', '.'));
            estado.disponible[i] = (isNaN(v) || v < 0) ? null : v;
            guardarAtributoResumen('caudal_disponible_' + claveSemana(), estado.disponible).then(function () {
                aviso('Caudal disponible del ' + PJ.DIAS_LARGO[i].toLowerCase() + ' guardado.');
            }).catch(function () { aviso('No se pudo guardar el caudal disponible.', 'error'); });
            calcular();
            pintarKpis(); pintarDias(); pintarPropuestas(); pintarGrupos();
            $c.find('.pj-input-disp[data-dia="' + (i + 1) + '"]').trigger('focus');
        });
    }

    function nombreGrupo(id) {
        var g = estado.grupos.find(function (x) { return x.id === id; });
        return g ? g.visible : id;
    }
    function pintarPropuestas() {
        var html = '';
        var fechasSem = PJ.fechasSemana(estado.lunes);
        var hoyF = PJ.fecha(Date.now());
        estado.reparto.forEach(function (r, i) {
            var dia = PJ.DIAS_LARGO[i];
            if (estado.disponible[i] === null) return;
            if (fechasSem[i] < hoyF) return; // días ya pasados: no se propone nada
            if (r.deficit > 0) {
                var parciales = [], aplazados = [];
                Object.keys(r.estado).forEach(function (id) {
                    if (r.estado[id] === 'parcial') parciales.push(id);
                    if (r.estado[id] === 'aplazado') aplazados.push(id);
                });
                // ¿Algún otro día con excedente donde reubicar los aplazados?
                var otros = estado.reparto.map(function (x, j) { return { j: j, sob: x.sobrante }; })
                    .filter(function (x) { return x.j !== i && estado.disponible[x.j] !== null && x.sob > PJ.UMBRAL_RIEGO_LS; });
                html += '<div class="pj-prop pj-prop-deficit"><div class="pj-prop-dia">' + dia + '</div><div>' +
                        '<b>Faltan ' + n0(r.deficit) + ' L/s.</b> Se asignan primero los turnos en curso y después las peticiones por orden de llegada.' +
                        (parciales.length ? '<div>Con caudal reducido: ' + parciales.map(function (id) { return '<span class="pj-tag pj-tag-parcial">' + esc(nombreGrupo(id)) + ' · ' + n1(r.asignado[id]) + ' L/s</span>'; }).join(' ') + '</div>' : '') +
                        (aplazados.length ? '<div>Sin agua este día (aplazar turno): ' + aplazados.map(function (id) { return '<span class="pj-tag pj-tag-aplazado">' + esc(nombreGrupo(id)) + '</span>'; }).join(' ') + '</div>' : '') +
                        (otros.length && aplazados.length ? '<div class="pj-prop-nota">Hay excedente el ' + otros.map(function (x) { return PJ.DIAS_LARGO[x.j].toLowerCase() + ' (+' + n0(x.sob) + ' L/s)'; }).join(', ') + ': se pueden reubicar ahí.</div>' : '') +
                        '</div></div>';
            } else if (r.sobrante > PJ.UMBRAL_RIEGO_LS) {
                var p = r.propuestas;
                html += '<div class="pj-prop pj-prop-excedente"><div class="pj-prop-dia">' + dia + '</div><div>' +
                        '<b>Sobran ' + n0(r.sobrante) + ' L/s.</b>' +
                        (p.adelantos.length ? '<div>Proponer adelanto de turno: ' + p.adelantos.map(function (a) {
                            return '<span class="pj-tag pj-tag-adelanto">' + esc(PJ.nombreConRemota(a.g.nombre)) + ' · pedido para el ' + PJ.DIAS_LARGO[a.diaPeticion].toLowerCase() + ' · ' + n1(a.q) + ' L/s</span>';
                        }).join(' ') + '</div>' : '<div class="pj-prop-nota">No hay peticiones posteriores que quepan en el sobrante.</div>') +
                        (p.balsas.length ? '<div>Llenado de balsas: ' + p.balsas.map(function (g) { return '<span class="pj-tag pj-tag-balsa">' + esc(PJ.nombreConRemota(g.nombre)) + '</span>'; }).join(' ') + '</div>' : '') +
                        '</div></div>';
            }
        });
        if (!html) {
            var hayDisp = estado.disponible.some(function (v) { return v !== null; });
            html = '<div class="pj-prop-vacio">' + (hayDisp ? 'El caudal disponible cubre la demanda prevista ajustadamente: no hay recortes ni excedentes que proponer.'
                                                         : 'Introduce el caudal disponible de cada día (fila "Caudal disponible") para calcular el reparto y las propuestas.') + '</div>';
        }
        $c.find('.pj-propuestas').html(html);
    }

    function pintarFiltros() {
        var sectores = {};
        estado.grupos.forEach(function (g) { if (g.sector !== null) sectores[g.sector] = true; });
        var ops = '<option value="">Todos los sectores</option>' + Object.keys(sectores).sort(function (a, b) { return a - b; })
            .map(function (k) { return '<option value="' + k + '"' + (String(estado.filtroSector) === k ? ' selected' : '') + '>Sector ' + k + '</option>'; }).join('');
        $c.find('.pj-filtros').html(
            '<select class="pj-sel-sector">' + ops + '</select>' +
            '<input type="text" class="pj-buscar" placeholder="Buscar grupo o remota (R77)…" value="' + esc(estado.filtroTexto) + '">' +
            '<label class="pj-check"><input type="checkbox" class="pj-solo"' + (estado.soloCambios ? ' checked' : '') + '> Solo con agua prevista, petición o parada</label>'
        );
        $c.find('.pj-leyenda-grupos').html('L/s previstos · <i class="pj-ley pj-c-completo"></i>asignado <i class="pj-ley pj-c-parcial"></i>reducido <i class="pj-ley pj-c-aplazado"></i>sin agua · <b>R</b> reserva <b>P</b> parada · <i class="pj-ley pj-ley-desv"></i>reserva fuera de umbral');
        $c.find('.pj-sel-sector').on('change', function () { estado.filtroSector = $(this).val(); pintarGrupos(); });
        $c.find('.pj-buscar').on('input', function () { estado.filtroTexto = $(this).val(); pintarGrupos(); });
        $c.find('.pj-solo').on('change', function () { estado.soloCambios = this.checked; pintarGrupos(); });
    }

    function pintarGrupos() {
        var hoy = PJ.fecha(Date.now());
        var fechas = PJ.fechasSemana(estado.lunes);
        var txt = norm(estado.filtroTexto);
        var lista = estado.grupos.filter(function (g) {
            if (estado.filtroSector !== '' && String(g.sector) !== String(estado.filtroSector)) return false;
            if (txt && norm(g.visible).indexOf(txt) === -1) return false;
            if (estado.soloCambios && !g.dias.some(function (d) { return d.q > 0 || d.R || d.P; })) return false;
            return true;
        }).sort(function (a, b) {
            var sa = a.sector === null ? 99 : a.sector, sb = b.sector === null ? 99 : b.sector;
            return sa !== sb ? sa - sb : a.nombre.localeCompare(b.nombre, 'es');
        });
        var cab = '<tr><th class="pj-col-sector">Sector</th><th class="pj-col-grupo">Grupo</th><th title="Caudal medio en días de riego">Base<small>L/s</small></th>' +
            fechas.map(function (f, i) { return '<th class="' + (f === hoy ? 'pj-hoy' : '') + '">' + PJ.DIAS[i] + '<small>' + new Date(PJ.sumarDias(estado.lunes, i)).getDate() + '</small></th>'; }).join('') +
            '<th>Semana<small>m³</small></th><th title="Proyección fijada el lunes">Fijada<small>m³</small></th></tr>';
        var filas = lista.map(function (g) {
            var semana = 0;
            var celdas = g.dias.map(function (d, i) {
                semana += d.q * 86.4;
                var r = estado.reparto[i];
                var est = r && r.estado[g.id];
                var cls = 'pj-c';
                if (d.q > 0 && estado.disponible[i] !== null) cls += ' pj-c-' + (est || 'completo');
                else if (d.q > 0) cls += ' pj-c-prev';
                if (fechas[i] === hoy) cls += ' pj-hoy';
                var dvC = d.R ? PJ.desviacionReserva(d, estado.umbralReserva) : null;
                if (dvC && dvC.fuera) cls += ' pj-c-desv';
                var marca = d.P ? '<b class="pj-m pj-m-p">P</b>' : (d.R ? '<b class="pj-m pj-m-r">R</b>' : '');
                var valor = d.q > 0 ? n1(est === 'parcial' || est === 'aplazado' ? r.asignado[g.id] : d.q) : '';
                var titulo = PJ.DIAS_LARGO[i] + ': ' + (d.q > 0 ? n1(d.q) + ' L/s previstos (' + d.motivo +
                             (d.pedido !== null ? '; histórico ' + (d.qHist !== null ? n1(d.qHist) + ' L/s' : 's/h') + (dvC ? ', ' + PJ.textoDesviacion(dvC) + (dvC.fuera ? ' FUERA DE UMBRAL' : '') : '') :
                               (d.k !== 1 ? ', calor ×' + (Math.round(d.k * 100) / 100) : '') + (d.lluviaLs > 0 ? ', lluvia −' + n1(d.lluviaLs) + ' L/s' : '')) + ')' : d.motivo) +
                             (d.sinCaudal ? ' · reserva sin caudal' : '') +
                             (est === 'parcial' ? ' · asignado ' + n1(r.asignado[g.id]) + ' L/s' : '') + (est === 'aplazado' ? ' · sin agua este día' : '') +
                             (d.pedidoEn ? ' · pedido el ' + new Date(d.pedidoEn).toLocaleString('es-ES', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) : '') +
                             (g.real[i] !== null && fechas[i] < hoy ? ' · real ' + n1(g.real[i]) + ' L/s' : '');
                return '<td class="' + cls + '" title="' + esc(titulo) + '">' + marca + valor + '</td>';
            }).join('');
            var fij = estado.fijada && estado.fijada.g && estado.fijada.g[g.id];
            var fijM3 = fij ? fij.reduce(function (a, q) { return a + q * 86.4; }, 0) : null;
            var fuente = g.baseInfo ? g.baseInfo.fuente : '';
            return '<tr><td class="pj-col-sector">' + (g.sector === null ? '–' : g.sector) + '</td>' +
                   '<td class="pj-col-grupo" title="' + esc(g.visible + (g.superficie ? ' · ' + n1(g.superficie) + ' ha' : ' · sin superficie')) + '">' + esc(g.visible) +
                   (g.activoInicio ? ' <span class="pj-activo" title="Venía regando al empezar la semana">●</span>' : '') + '</td>' +
                   '<td class="pj-base' + (PJ.esAtipico(g.base, g.superficie) ? ' pj-atipico' : '') + '" title="' + esc(fuente + (g.baseInfo && g.baseInfo.diasRiego ? ' · ' + g.baseInfo.diasRiego + ' días con riego' : '') +
