    /* ---------- acciones ---------- */
    function aprobarReparto() {
        if (!estado.reparto) return;
        if (!estado.disponible.some(function (v) { return v !== null; })) {
            aviso('Introduce primero el caudal disponible de algún día.', 'error'); return;
        }
        var asignaciones = {};
        estado.grupos.forEach(function (g) {
            var fila = estado.reparto.map(function (r) { return r.asignado[g.id] || 0; });
