            estado.aprobado = aprob; pintarEstadoFijada(); aviso('Reparto aprobado y guardado.');
        }).catch(function () { aviso('No se pudo guardar el reparto aprobado.', 'error'); });
    }
    function exportarCsv() {
        if (!estado.grupos.length) return;
        var fechas = PJ.fechasSemana(estado.lunes);
        var cab = ['Sector', 'Grupo', 'Superficie (ha)', 'Caudal base (L/s)', 'Origen base']
            .concat(fechas.map(function (f, i) { return PJ.DIAS[i] + ' ' + f + ' previsto (L/s)'; }))
            .concat(fechas.map(function (f, i) { return PJ.DIAS[i] + ' histórico (L/s)'; }))
            .concat(fechas.map(function (f, i) { return PJ.DIAS[i] + ' reservado (L/s)'; }))
            .concat(fechas.map(function (f, i) { return PJ.DIAS[i] + ' asignado (L/s)'; }))
            .concat(['Semana (m³)']);
        function celda(v) { var t = String(v == null ? '' : v); return /[";\r\n]/.test(t) ? '"' + t.replace(/"/g, '""') + '"' : t; }
        function num(v) { return (v === null || v === undefined || isNaN(v)) ? '' : String(Math.round(v * 10) / 10).replace('.', ','); }
        var filas = estado.grupos.map(function (g) {
            var sem = 0; g.dias.forEach(function (d) { sem += d.q * 86.4; });
            return [g.sector, g.visible, num(g.superficie), num(g.base), g.baseInfo ? g.baseInfo.fuente : '']
                .concat(g.dias.map(function (d) { return (d.P ? 'P ' : d.R ? 'R ' : '') + num(d.q); }))
                .concat(g.dias.map(function (d) { return num(d.qHist); }))
                .concat(g.dias.map(function (d) { return d.pedido !== null ? num(d.pedido) : ''; }))
