        var csv = [cab].concat(filas).map(function (f) { return f.map(celda).join(';'); }).join('\r\n');
        var blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' });
        var url = URL.createObjectURL(blob);
        var a = document.createElement('a');
        a.href = url; a.download = 'proyeccion_' + claveSemana() + '.csv';
        document.body.appendChild(a); a.click(); document.body.removeChild(a);
        setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
    }

    /* ---------- gemelo digital y pestañas ---------- */
    var gemelo = crearGemelo({
        $c: $c, estado: estado, settings: s, perfilNombre: PROFILE_NAME,
        esc: esc, n0: n0, n1: n1, get: get, post: post, meteoDe: meteoDe,
        umbralReserva: function () { return estado.umbralReserva; },
        recalcularTodo: function () { calcular(); if (estado.vista === 'tabla') pintarTodo(); }
    });
    var semanaGemelo = null;
    function arrancarGemelo() {
        if (!estado.reparto || estado.cargando) return;
        if (!gemelo.iniciado) { semanaGemelo = estado.lunes; gemelo.iniciar(); }
        else if (semanaGemelo !== estado.lunes) { semanaGemelo = estado.lunes; gemelo.nuevaSemana(); }
    }
    function mostrarVista(v) {
        estado.vista = v;
        $c.find('.pj-pestana').removeClass('activa').filter('[data-vista="' + v + '"]').addClass('activa');
        $c.find('.pj-cuerpo').toggle(v === 'tabla');
        $c.find('.gm').toggle(v === 'gemelo');
        if (v === 'gemelo') arrancarGemelo(); else pintarTodo();
    }
    $c.find('.pj-pestana').on('click', function () { mostrarVista($(this).attr('data-vista')); });

    $c.find('.pj-btn-prev').on('click', function () { estado.lunes = PJ.sumarDias(estado.lunes, -7); cargarSemana(); });
    $c.find('.pj-btn-next').on('click', function () { estado.lunes = PJ.sumarDias(estado.lunes, 7); cargarSemana(); });
    $c.find('.pj-btn-hoy').on('click', function () { estado.lunes = PJ.lunesDe(Date.now()); cargarSemana(); });
    $c.find('.pj-btn-pedir').on('click', function () { estado.lunes = PJ.sumarDias(PJ.lunesDe(Date.now()), 7); cargarSemana(); });
    $c.find('.pj-btn-recalcular').on('click', function () {
        try { localStorage.removeItem('pj-meteo-' + claveSemana()); } catch (e) {}
        cargarSemana();
    });
    $c.find('.pj-btn-aprobar').on('click', aprobarReparto);
    $c.find('.pj-btn-csv').on('click', exportarCsv);

    pintarCabecera();
    setTimeout(cargarSemana, 150);
};

self.onDestroy = function () {
